import os
import time
import json
import random
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Set

import requests
from tqdm.auto import tqdm

# ---------- Helpers ----------
def ensure_values():
    missing = []
    if not USERNAME or USERNAME.strip().lower() in {"paste_twitter_username_here", "username"}:
        missing.append("USERNAME")
    if not AUTH_TOKEN or "PASTE_YOUR_auth_token" in AUTH_TOKEN:
        missing.append("AUTH_TOKEN")
    if not CT0 or "PASTE_YOUR_ct0" in CT0:
        missing.append("CT0")
    if not WEB_BEARER or "PASTE_CURRENT_WEB_BEARER_TOKEN_HERE" in WEB_BEARER:
        missing.append("WEB_BEARER")
    if missing:
        raise ValueError(f"Please paste valid values for: {', '.join(missing)}")


def build_session(auth_token: str, ct0: str, bearer: str) -> requests.Session:
    s = requests.Session()
    # Minimal, stable headers used by the web app
    s.headers.update({
        "Authorization": f"Bearer {bearer}",
        "x-csrf-token": ct0,
        "x-twitter-active-user": "yes",
        "x-twitter-client-language": "en",
        "accept": "*/*",
        "accept-language": "en-US,en;q=0.9",
        "referer": "https://twitter.com/",
        # A realistic desktop UA reduces the chance of anti-bot friction
        "user-agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
            "(KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36"
        ),
    })
    # Set cookies (domain .twitter.com so they apply to API subdomains)
    s.cookies.set("auth_token", auth_token, domain=".twitter.com")
    s.cookies.set("ct0", ct0, domain=".twitter.com")
    return s


def jitter_sleep(a: float, b: float):
    time.sleep(random.uniform(a, b))


def make_output_dir(base: str, username: str) -> str:
    out = os.path.join(base, username)
    Path(out).mkdir(parents=True, exist_ok=True)
    return out


def orig_image_url(url: str) -> str:
    # Ensure original size. pbs media often supports ?name=orig.
    if "?" in url:
        base, _, qs = url.partition("?")
        params = [p for p in qs.split("&") if p and not p.startswith("name=")]
        params.append("name=orig")
        return base + "?" + "&".join(params)
    return url + "?name=orig"


def parse_photo_urls_from_search_adaptive(resp: Dict) -> List[Tuple[str, str]]:
    """
    Extract (tweet_id, photo_url) from search/adaptive response.
    Only photo media (ignores videos/GIFs).
    """
    results = []
    tweets = resp.get("globalObjects", {}).get("tweets", {}) or {}
    for tid, tw in tweets.items():
        ext = tw.get("extended_entities", {}) or {}
        media_list = ext.get("media", []) or []
        for m in media_list:
            if m.get("type") == "photo":
                u = m.get("media_url_https") or m.get("media_url")
                if u:
                    results.append((tid, orig_image_url(u)))
    return results


def _find_bottom_cursor_in_entries(entries: List[Dict]) -> Optional[str]:
    for e in entries:
        content = e.get("content") or {}
        if content.get("entryType") == "TimelineTimelineCursor" or content.get("cursorType"):
            # Some variants store cursor directly
            if content.get("cursorType") == "Bottom":
                val = content.get("value") or content.get("cursorValue")
                if val:
                    return val
        # Newer structures nest inside content["operation"]["cursor"]
        op = content.get("operation") or {}
        cursor = op.get("cursor") or {}
        if cursor.get("cursorType") == "Bottom":
            val = cursor.get("value") or cursor.get("cursorValue")
            if val:
                return val
        # Some entries wrap inside itemContent
        item = content.get("itemContent") or {}
        c2 = item.get("value") or item.get("content") or {}
        if isinstance(c2, dict) and c2.get("cursorType") == "Bottom":
            val = c2.get("value") or c2.get("cursorValue")
            if val:
                return val
    return None


def extract_next_cursor(resp: Dict) -> Optional[str]:
    timeline = resp.get("timeline", {}) or {}
    instructions = timeline.get("instructions", []) or []
    for instr in instructions:
        if "addEntries" in instr:
            entries = instr["addEntries"].get("entries", []) or []
            c = _find_bottom_cursor_in_entries(entries)
            if c:
                return c
        if "replaceEntry" in instr:
            entry = instr["replaceEntry"].get("entry", {}) or {}
            entries = [entry] if entry else []
            c = _find_bottom_cursor_in_entries(entries)
            if c:
                return c
    return None


def download_with_retries(session: requests.Session, url: str, dest_path: str, retries: int = 3) -> bool:
    for attempt in range(1, retries + 1):
        try:
            r = session.get(url, stream=True, timeout=45)
            if r.status_code == 200:
                tmp = dest_path + ".part"
                with open(tmp, "wb") as f:
                    for chunk in r.iter_content(chunk_size=1024 * 256):
                        if chunk:
                            f.write(chunk)
                os.replace(tmp, dest_path)
                return True
            else:
                print(f"[download] HTTP {r.status_code} for {url} (attempt {attempt}/{retries})")
        except requests.RequestException as e:
            print(f"[download] Error: {e} (attempt {attempt}/{retries})")
        time.sleep(1.0 * attempt)
    return False


# ---------- Main ----------
try:
    ensure_values()

    session = build_session(AUTH_TOKEN, CT0, WEB_BEARER)

    out_dir = make_output_dir(OUTPUT_DIR, USERNAME)
    archive_file = os.path.join(out_dir, "downloaded.txt")
    seen: Set[str] = set()
    if os.path.exists(archive_file):
        with open(archive_file, "r", encoding="utf-8") as f:
            for line in f:
                s = line.strip()
                if s:
                    seen.add(s)

    # search/adaptive media timeline for a user via filter:images
    # This mimics the web client. We first resolve the numeric user id via /i/api/graphql or use search by from:username.
    # To avoid relying on another endpoint, we use search with (from:username) filter:images and paginate via cursor.

    base_url = "https://api.twitter.com/2/search/adaptive.json"

    # Query parameters closely resembling the web client's request for images from a single author
    def build_params(cursor: Optional[str] = None) -> Dict[str, str]:
        q = f"from:{USERNAME} filter:images -filter:replies"
        p = {
            "q": q,
            "count": "50",
            "tweet_search_mode": "live",
            "query_source": "typed_query",
            "pc": "1",
            "spelling_corrections": "1",
            "result_filter": "tweet_photo",
            "include_ext_alt_text": "true",
            "include_entities": "true",
            "simple_quoted_tweet": "true",
            "tweet_mode": "extended",
        }
        if cursor:
            p["cursor"] = cursor
        return p

    photo_urls: List[Tuple[str, str]] = []
    cursor: Optional[str] = None

    for page in range(1, MAX_PAGES + 1):
        params = build_params(cursor)

        # Request with retries
        ok = False
        last_exc = None
        for attempt in range(1, REQUEST_RETRIES + 1):
            try:
                r = session.get(base_url, params=params, timeout=45)
                if r.status_code == 200:
                    data = r.json()
                    ok = True
                    break
                elif r.status_code in (401, 403):
                    raise RuntimeError(f"Auth failed (HTTP {r.status_code}). Check auth_token/ct0/bearer and permissions.")
                else:
                    print(f"[timeline] HTTP {r.status_code} (attempt {attempt}/{REQUEST_RETRIES})")
            except (requests.RequestException, ValueError) as e:
                last_exc = e
                print(f"[timeline] Error: {e} (attempt {attempt}/{REQUEST_RETRIES})")
            time.sleep(1.0 * attempt)

        if not ok:
            raise RuntimeError(f"Failed to fetch timeline after {REQUEST_RETRIES} attempts. Last error: {last_exc}")

        new_pairs = parse_photo_urls_from_search_adaptive(data)
        added = 0
        for tid, url in new_pairs:
            if url not in {u for _, u in photo_urls}:
                photo_urls.append((tid, url))
                added += 1

        nxt = extract_next_cursor(data)
        print(f"Page {page}: +{added} photos; cursor: {'present' if nxt else 'none'}")

        if not nxt:
            break
        cursor = nxt
        jitter_sleep(SLEEP_MIN, SLEEP_MAX)

    # Download
    print(f"Total unique photo URLs found: {len(photo_urls)}")
    downloaded_now = 0
    for tid, url in tqdm(photo_urls, desc="Downloading photos"):
        if url in seen:
            continue
        fname = url.split("/")[-1].split("?")[0]
        # Ensure unique filenames per tweet + index when duplicates exist
        dest = os.path.join(out_dir, f"{tid}_{fname}")
        if download_with_retries(session, url, dest, retries=DOWNLOAD_RETRIES):
            seen.add(url)
            downloaded_now += 1
            with open(archive_file, "a", encoding="utf-8") as f:
                f.write(url + "\n")
        else:
            print(f"[warn] Failed to download: {url}")

    print(f"Done. Saved {downloaded_now} new images to: {out_dir}")

except Exception as e:
    print(f"Fatal error: {e}")
    raise
