		{0.01, 0.00, 0.02, 0.01, 0.09},
	}

	n := len(expectedReturns)

	// Per-asset bounds (e.g., min 0%, max 60%)
	minW := make([]float64, n)
	maxW := make([]float64, n)
	for i := 0; i < n; i++ {
		minW[i] = 0.0
		maxW[i] = 0.6
	}

	// GA hyperparameters
	popSize := 200
	generations := 300
	crossoverRate := 0.9
	mutationRate := 0.1
	mutationSigma := 0.05
	tournamentSize := 3
	elitism := 2

	// Risk aversion (lambda): higher penalizes variance more
	riskAversion := 0.5

	// Ensure feasibility of bounds
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0+1e-9 || sumMax < 1.0-1e-9 {
		log.Fatalf("Infeasible bounds: sum(min)=%.6f, sum(max)=%.6f; cannot sum to 1", sumMin, sumMax)
	}

	// Initialize population
	pop := make([]Individual, popSize)
	for i := 0; i < popSize; i++ {
		w := randomFeasibleWeights(n, minW, maxW)
		f := objective(w, expectedReturns, cov, riskAversion)
		pop[i] = Individual{Weights: w, Fitness: f}
	}

	best := bestIndividual(pop)
	fmt.Println("Initial best fitness:", best.Fitness)
	fmt.Println("Initial weights:", pretty(best.Weights))

	for gen := 0; gen < generations; gen++ {
		// Sort population by fitness (descending)
		pop = sortByFitness(pop)

		// Keep elites
		nextPop := make([]Individual, 0, popSize)
		for i := 0; i < elitism && i < len(pop); i++ {
			nextPop = append(nextPop, copyIndividual(pop[i]))
		}

		// Generate rest via selection, crossover, mutation
		for len(nextPop) < popSize {
			parent1 := tournamentSelect(pop, tournamentSize)
			parent2 := tournamentSelect(pop, tournamentSize)

			child1 := copyIndividual(parent1)
			child2 := copyIndividual(parent2)

			if rand.Float64() < crossoverRate {
				child1, child2 = uniformCrossover(parent1, parent2)
			}

			mutate(&child1, mutationRate, mutationSigma)
			mutate(&child2, mutationRate, mutationSigma)

			// Repair and re-evaluate
			projectToSimplexWithBounds(child1.Weights, minW, maxW)
			child1.Fitness = objective(child1.Weights, expectedReturns, cov, riskAversion)

			projectToSimplexWithBounds(child2.Weights, minW, maxW)
			child2.Fitness = objective(child2.Weights, expectedReturns, cov, riskAversion)

			nextPop = append(nextPop, child1)
			if len(nextPop) < popSize {
				nextPop = append(nextPop, child2)
			}
		}

		pop = nextPop
		currentBest := bestIndividual(pop)

		// Simple logging
		if (gen+1)%25 == 0 || gen == generations-1 {
			fmt.Printf("Gen %d | Best fitness: %.6f | Weights: %s\n",
				gen+1, currentBest.Fitness, pretty(currentBest.Weights))
		}
	}

	// Final result
	pop = sortByFitness(pop)
	best = pop[0]
	fmt.Println("\nFinal best fitness:", best.Fitness)
	fmt.Println("Final weights:", pretty(best.Weights))
	fmt.Printf("Expected return: %.6f, Variance: %.6f\n",
		dot(best.Weights, expectedReturns),
		quadForm(best.Weights, cov))
}

// Objective: maximize return - lambda * variance
func objective(w []float64, expected []float64, cov [][]float64, lambda float64) float64 {
	ret := dot(w, expected)
	variance := quadForm(w, cov)
	return ret - lambda*variance
}

// Create a random feasible weight vector summing to 1 within bounds.
func randomFeasibleWeights(n int, minW, maxW []float64) []float64 {
	w := make([]float64, n)
	sum := 0.0
	for i := 0; i < n; i++ {
		w[i] = rand.Float64() + 1e-12
		sum += w[i]
	}
	for i := 0; i < n; i++ {
		w[i] /= sum
	}
	projectToSimplexWithBounds(w, minW, maxW)
	return w
}

// Projects a vector w onto the simplex {y: sum y = 1, minW[i] <= y[i] <= maxW[i]}.
// Uses bisection on a Lagrange multiplier tau: y_i = clip(w_i - tau, minW[i], maxW[i]) such that sum_i y_i = 1.
func projectToSimplexWithBounds(w []float64, minW, maxW []float64) {
	n := len(w)

	// Feasibility check
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0 {
		copy(w, minW)
		return
	}
	if sumMax < 1.0 {
		copy(w, maxW)
		return
	}

	// Determine bounds for tau
	tauLow := math.Inf(1)
	tauHigh := math.Inf(-1)
	for i := 0; i < n; i++ {
		low := w[i] - maxW[i]  // if tau <= low => y_i = maxW[i]
		high := w[i] - minW[i] // if tau >= high => y_i = minW[i]
		if low < tauLow {
			tauLow = low
		}
		if high > tauHigh {
			tauHigh = high
		}
	}

	// Bisection on tau
	for iter := 0; iter < 80; iter++ {
		tau := 0.5 * (tauLow + tauHigh)
		sum := 0.0
		for i := 0; i < n; i++ {
			v := w[i] - tau
			if v < minW[i] {
				v = minW[i]
			}
			if v > maxW[i] {
				v = maxW[i]
			}
			sum += v
		}
		if sum > 1.0 {
			// Need to reduce sum -> increase tau
			tauLow = tau
		} else {
			// Need to increase sum -> decrease tau
			tauHigh = tau
		}
	}

	tau := 0.5 * (tauLow + tauHigh)
	for i := 0; i < n; i++ {
		v := w[i] - tau
		if v < minW[i] {
			v = minW[i]
		}
		if v > maxW[i] {
			v = maxW[i]
		}
		w[i] = v
	}

	// Optional tiny correction for numerical drift
	sum := 0.0
	freeIdx := make([]int, 0, n)
	for i := 0; i < n; i++ {
		sum += w[i]
		if w[i] > minW[i]+1e-12 && w[i] < maxW[i]-1e-12 {
			freeIdx = append(freeIdx, i)
		}
	}
	diff := 1.0 - sum
	if math.Abs(diff) > 1e-10 && len(freeIdx) > 0 {
		step := diff / float64(len(freeIdx))
		for _, i := range freeIdx {
			w[i] += step
			if w[i] < minW[i] {
				w[i] = minW[i]
			}
			if w[i] > maxW[i] {
				w[i] = maxW[i]
			}
		}
	}
}

// Tournament selection (maximization): pick 'k' random individuals, return the best
func tournamentSelect(pop []Individual, k int) Individual {
	best := pop[rand.Intn(len(pop))]
	for i := 1; i < k; i++ {
		cand := pop[rand.Intn(len(pop))]
		if cand.Fitness > best.Fitness {
			best = cand
		}
	}
	return best
}

// Uniform crossover: for each gene, pick from parent1 or parent2 with p=0.5
func uniformCrossover(p1, p2 Individual) (Individual, Individual) {
	n := len(p1.Weights)
	child1 := Individual{Weights: make([]float64, n)}
	child2 := Individual{Weights: make([]float64, n)}
	for i := 0; i < n; i++ {
		if rand.Float64() < 0.5 {
			child1.Weights[i] = p1.Weights[i]
			child2.Weights[i] = p2.Weights[i]
		} else {
			child1.Weights[i] = p2.Weights[i]
			child2.Weights[i] = p1.Weights[i]
		}
	}
	// Fitness will be recomputed after repair
	child1.Fitness = 0.0
	child2.Fitness = 0.0
	return child1, child2
}

// mutate adds Gaussian noise to each gene with probability mutationRate
func mutate(ind *Individual, mutationRate, mutationSigma float64) {
	for i := range ind.Weights {
		if rand.Float64() < mutationRate {
			ind.Weights[i] += mutationSigma * rand.NormFloat64()
		}
	}
	// Note: projection + fitness recalculation happens in the main loop.
}

// copyIndividual creates a deep copy of an individual
func copyIndividual(ind Individual) Individual {
	w := make([]float64, len(ind.Weights))
	copy(w, ind.Weights)
	return Individual{Weights: w, Fitness: ind.Fitness}
}

// sortByFitness sorts a population by fitness in descending order and returns it
func sortByFitness(pop []Individual) []Individual {
	sort.Slice(pop, func(i, j int) bool {
		return pop[i].Fitness > pop[j].Fitness
	})
	return pop
}

// bestIndividual returns the individual with the highest fitness
func bestIndividual(pop []Individual) Individual {
	best := pop[0]
	for i := 1; i < len(pop); i++ {
		if pop[i].Fitness > best.Fitness {
			best = pop[i]
		}
	}
	return best
}

// dot computes the dot product of two vectors
func dot(a, b []float64) float64 {
	if len(a) != len(b) {
		panic("dot: length mismatch")
	}
	sum := 0.0
	for i := 0; i < len(a); i++ {
		sum += a[i] * b[i]
	}
	return sum
}

// quadForm computes w^T * cov * w
func quadForm(w []float64, cov [][]float64) float64 {
	n := len(w)
	sum := 0.0
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			sum += w[i] * cov[i][j] * w[j]
		}
	}
	return sum
}

// pretty formats a slice of float64 nicely
func pretty(w []float64) string {
	var b strings.Builder
	b.WriteString("[")
	for i, v := range w {
		if i > 0 {
			b.WriteString(" ")
		}
		b.WriteString(fmt.Sprintf("%.4f", v))
	}
	b.WriteString("]")
	return b.String()
}
