}

static std::wstring FormatLastError() {
    DWORD err = GetLastError();
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               nullptr, err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown error)";
    if (buf) LocalFree(buf);
    return s;
}

struct WinHttpHandle {
    HINTERNET h{nullptr};
    WinHttpHandle() = default;
    explicit WinHttpHandle(HINTERNET x) : h(x) {}
    ~WinHttpHandle() { if (h) WinHttpCloseHandle(h); }
    WinHttpHandle(const WinHttpHandle&) = delete;
    WinHttpHandle& operator=(const WinHttpHandle&) = delete;
    WinHttpHandle(WinHttpHandle&& o) noexcept : h(o.h) { o.h = nullptr; }
    WinHttpHandle& operator=(WinHttpHandle&& o) noexcept {
        if (this != &o) { if (h) WinHttpCloseHandle(h); h = o.h; o.h = nullptr; }
        return *this;
    }
    operator HINTERNET() const { return h; }
};

static bool ParseUrl(const std::wstring& url, std::wstring& host, INTERNET_PORT& port, std::wstring& path, bool& https) {
    URL_COMPONENTS uc{}; uc.dwStructSize = sizeof(uc);
    wchar_t hostbuf[256] = {0}; wchar_t pathbuf[2048] = {0};
    uc.lpszHostName = hostbuf; uc.dwHostNameLength = _countof(hostbuf);
    uc.lpszUrlPath = pathbuf; uc.dwUrlPathLength = _countof(pathbuf);
    if (!WinHttpCrackUrl(url.c_str(), (DWORD)url.size(), 0, &uc)) return false;
    https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    host.assign(uc.lpszHostName, uc.dwHostNameLength);
    port = uc.nPort ? uc.nPort : (https ? 443 : 80);
    path.assign(uc.lpszUrlPath && uc.dwUrlPathLength ? uc.lpszUrlPath : L"/", uc.dwUrlPathLength ? uc.dwUrlPathLength : 1);
    if (path.empty()) path = L"/";
    return true;
}

static bool HttpRequest(const std::wstring& url, const std::wstring& method, const std::string* body, std::string& out) {
    out.clear();
    std::wstring host, path; INTERNET_PORT port = 0; bool https = false;
    if (!ParseUrl(url, host, port, path, https)) {
        std::wcerr << L"Invalid URL: " << url << L"\n";
        return false;
    }
    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP Tor-Client-Sample/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) { std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n"; return false; }

    WinHttpHandle hConnect(WinHttpConnect(hSession, host.c_str(), port, 0));
    if (!hConnect) { std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n"; return false; }

    DWORD flags = https ? WINHTTP_FLAG_SECURE : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), path.c_str(), nullptr,
                                              WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest) { std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n"; return false; }

    if (https) {
        DWORD secFlags = SECURITY_FLAG_IGNORE_CERT_CN_INVALID | SECURITY_FLAG_IGNORE_CERT_DATE_INVALID |
                         SECURITY_FLAG_IGNORE_UNKNOWN_CA | SECURITY_FLAG_IGNORE_CERT_WRONG_USAGE;
        WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &secFlags, sizeof(secFlags));
    }

    BOOL b = FALSE;
    if (body) {
        std::wstring headers = L"Content-Type: application/x-www-form-urlencoded\r\n";
        b = WinHttpSendRequest(hRequest, headers.c_str(), (DWORD)-1L,
                               (LPVOID)body->data(), (DWORD)body->size(), (DWORD)body->size(), 0);
    } else {
        b = WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
    }
    if (!b) { std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n"; return false; }

    if (!WinHttpReceiveResponse(hRequest, nullptr)) {
        std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n"; return false; }

    DWORD status = 0, len = sizeof(status);
    if (!WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX,
                             &status, &len, WINHTTP_NO_HEADER_INDEX)) {
        std::wcerr << L"WinHttpQueryHeaders status failed: " << FormatLastError() << L"\n"; return false; }
    if (status < 200 || status >= 300) {
        std::wcerr << L"HTTP status: " << status << L" for URL: " << url << L"\n";
    }

    std::string buf; buf.reserve(32 * 1024);
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) {
            std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n"; return false; }
        if (!avail) break;
        std::vector<char> chunk(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, chunk.data(), avail, &read)) {
            std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n"; return false; }
        buf.append(chunk.data(), chunk.data() + read);
    }
    out.swap(buf);
    return true;
}

static bool HttpGet(const std::wstring& url, std::string& out) { return HttpRequest(url, L"GET", nullptr, out); }
static bool HttpPost(const std::wstring& url, const std::string& body, std::string& out) { return HttpRequest(url, L"POST", &body, out); }

