static std::string ToLower(std::string s){ std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c){return (char)std::tolower(c);}); return s; }

// Base32 (RFC 4648, lowercase) decode for v3 onions
static bool Base32Decode(const std::string& in, std::vector<uint8_t>& out) {
    static const int8_t map[256] = {
        -1
    };
    // Build map on first use
    static bool inited=false; static int8_t tbl[256];
    if(!inited){
        std::fill(std::begin(tbl), std::end(tbl), -1);
        const std::string alpha = "abcdefghijklmnopqrstuvwxyz234567";
        for(size_t i=0;i<alpha.size();++i) tbl[(uint8_t)alpha[i]]=(int8_t)i;
        inited=true;
    }
    uint32_t buffer=0; int bitsLeft=0; out.clear(); out.reserve(in.size()*5/8);
    for(unsigned char c: in){
        if (c=='=') break;
        int8_t v = tbl[c]; if(v<0) continue; // skip non alphabet
        buffer = (buffer<<5) | (uint32_t)v; bitsLeft += 5;
        while(bitsLeft>=8){ bitsLeft-=8; out.push_back((uint8_t)((buffer>>bitsLeft)&0xFF)); }
    }
    return true;
}

// Validate and extract ed25519 pubkey from a v3 .onion (56 chars base32, lower-case)
static bool ParseOnionV3(const std::string& onionHost, std::array<uint8_t,32>& pubkey_out) {
    std::string host = onionHost;
    auto pos = host.find(".onion"); if (pos!=std::string::npos) host = host.substr(0,pos);
    host = ToLower(host);
    if (host.size()!=56) return false;
    std::vector<uint8_t> dec;
    if(!Base32Decode(host, dec)) return false;
    if(dec.size()!=35) return false; // 32 pub + 2 checksum + 1 version
    uint8_t ver = dec[34]; if (ver != 3) return false;
    std::copy(dec.begin(), dec.begin()+32, pubkey_out.begin());
    return true;
}

// Very minimal consensus parser: pulls relay nickname, fingerprint, flags
struct RelayInfo { std::string nickname; std::string fingerprint; std::string flags; };
static std::vector<RelayInfo> ParseConsensus(const std::string& text) {
    std::vector<RelayInfo> relays; RelayInfo cur; bool inRouter=false;
    std::istringstream iss(text); std::string line;
    while(std::getline(iss, line)){
        if(line.size() && line.back()=='\r') line.pop_back();
        if(line.rfind("r ",0)==0){
            if(inRouter){ relays.push_back(cur); cur = RelayInfo{}; }
            inRouter=true;
            std::istringstream ls(line.substr(2));
            ls >> cur.nickname; // nickname
        } else if(line.rfind("s ",0)==0){
            cur.flags = line.substr(2);
        } else if(line.rfind("f ",0)==0){
            // microdescriptor "f" line has digest; for illustration, store as fingerprint placeholder
            cur.fingerprint = line.substr(2);
        }
    }
    if(inRouter) relays.push_back(cur);
    return relays;
}

// Minimal v3 HS descriptor parser: extracts fields from text blocks
struct HSDescriptorInfo {
    std::string desc_signing_key;
    std::string revision_counter;
    std::vector<std::string> intro_points; // base64 blocks
};

static std::string Trim(const std::string& s){ size_t a=s.find_first_not_of(" \t\r\n"); size_t b=s.find_last_not_of(" \t\r\n"); if(a==std::string::npos) return ""; return s.substr(a,b-a+1);} 

static HSDescriptorInfo ParseHSDescriptor(const std::string& text) {
    HSDescriptorInfo info; std::istringstream iss(text); std::string line;
    bool inBlock=false; std::string blockName, blockData;
    while(std::getline(iss,line)){
        if(line.size() && line.back()=='\r') line.pop_back();
        if(line.rfind("revision-counter ",0)==0){ info.revision_counter = Trim(line.substr(17)); }
        if(line.rfind("descriptor-signing-key",0)==0){
            // next lines until END are key
            inBlock=false; blockName.clear(); blockData.clear();
        }
        if(line.rfind("-----BEGIN",0)==0){ inBlock=true; blockName=line; blockData.clear(); continue; }
        if(line.rfind("-----END",0)==0){
            inBlock=false;
            if(blockName.find("ED25519 CERT")!=std::string::npos || blockName.find("PUBLIC KEY")!=std::string::npos){
                info.desc_signing_key = blockData;
            } else if(blockName.find("MESSAGE")!=std::string::npos){
                info.intro_points.push_back(blockData);
            }
            blockName.clear(); blockData.clear();
            continue;
        }
        if(inBlock){ blockData.append(line); blockData.push_back('\n'); }
    }
    return info;
}

