        else if(a==L"--descriptor-url" && i+1<argc) hsdescUrl = argv[++i];
        else if(a==L"--get-onion" && i+1<argc) onionGatewayUrl = argv[++i];
        else if(a==L"--post-onion" && i+2<argc) { onionGatewayUrl = argv[++i]; postData = argv[++i]; }
    }

    if(!consensusUrl.empty()){
        std::string body;
        if(HttpGet(consensusUrl, body)){
            auto relays = ParseConsensus(body);
            PrintRelaysSample(relays);
        } else {
            std::wcerr << L"Failed to download consensus from: " << consensusUrl << L"\n";
        }
    }

    if(!hsdescUrl.empty()){
        std::string body;
        if(HttpGet(hsdescUrl, body)){
            auto d = ParseHSDescriptor(body);
            PrintHSDescriptorSummary(d);
        } else {
            std::wcerr << L"Failed to download HS descriptor from: " << hsdescUrl << L"\n";
        }
    }

    if(!onionGatewayUrl.empty()){
        std::string response;
        if(postData.empty()){
            if(HttpGet(onionGatewayUrl, response)){
                std::cout << "GET response size: " << response.size() << " bytes\n";
            } else {
                std::wcerr << L"GET to onion gateway failed: " << onionGatewayUrl << L"\n";
            }
        } else {
            std::string post = WideToUtf8(postData);
            if(HttpPost(onionGatewayUrl, post, response)){
                std::cout << "POST response size: " << response.size() << " bytes\n";
            } else {
                std::wcerr << L"POST to onion gateway failed: " << onionGatewayUrl << L"\n";
            }
        }
    }

    // Example: parse a provided .onion host from env var ONION_HOST
    wchar_t envBuf[256]; DWORD n = GetEnvironmentVariableW(L"ONION_HOST", envBuf, _countof(envBuf));
    if(n>0 && n < _countof(envBuf)){
        std::string onion = WideToUtf8(envBuf);
        std::array<uint8_t,32> pk;
        if(ParseOnionV3(onion, pk)){
            std::cout << ".onion pubkey: ";
            for(auto b: pk) std::cout << std::hex << std::setw(2) << std::setfill('0') << (int)b;
            std::cout << std::dec << "\n";
        } else {
            std::cout << "Invalid v3 .onion: " << onion << "\n";
        }
    }

    return 0;
}

// tor_client_scaffold.cpp
//
// Single-file C++ (Windows) that:
// - Uses WinHTTP for HTTPS GET/POST with robust error handling.
// - Downloads a Tor consensus document from a provided HTTPS URL and parses key fields.
// - Downloads a Tor v3 hidden-service descriptor from a provided HTTPS URL and parses key fields.
// - Validates and decodes a v3 .onion address (base32 -> pubkey/checksum/version) using OpenSSL SHA3-256.
//
// Build (MSVC example):
//   cl /std:c++17 /O2 /EHsc tor_client_scaffold.cpp winhttp.lib ws2_32.lib crypt32.lib
//
// Usage examples:
//   tor_client_scaffold.exe --consensus-url https://collector.torproject.org/recent/relay-descriptors/consensuses/2024-01-01-00-00-00-consensus
//   tor_client_scaffold.exe --descriptor-url https://example.com/sample_hs_descriptor.txt
//   tor_client_scaffold.exe --get https://example.com/
//   tor_client_scaffold.exe --post https://httpbin.org/post "name=value&x=y"
//   tor_client_scaffold.exe --onion-check facebookcorewwwi.onion

