// -------------------- Utility: UTF-16/UTF-8 conversions --------------------
static std::wstring Utf8ToWide(const std::string& s) {
    if (s.empty()) return L"";
    int len = MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0);
    std::wstring out(len, 0);
    MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), &out[0], len);
    return out;
}

static std::string WideToUtf8(const std::wstring& ws) {
    if (ws.empty()) return "";
    int len = WideCharToMultiByte(CP_UTF8, 0, ws.c_str(), (int)ws.size(), nullptr, 0, nullptr, nullptr);
    std::string out(len, 0);
    WideCharToMultiByte(CP_UTF8, 0, ws.c_str(), (int)ws.size(), &out[0], len, nullptr, nullptr);
    return out;
}

// -------------------- WinHTTP helpers --------------------
static std::wstring FormatWinHttpError(DWORD err) {
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_HMODULE | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               GetModuleHandleW(L"winhttp.dll"), err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown WinHTTP error)";
    if (buf) LocalFree(buf);
    return s;
}

static std::wstring FormatLastError() {
    DWORD err = GetLastError();
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               nullptr, err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown error)";
    if (buf) LocalFree(buf);
    return s;
}

struct WinHttpHandle {
    HINTERNET h{nullptr};
    WinHttpHandle() = default;
    explicit WinHttpHandle(HINTERNET handle) : h(handle) {}
    ~WinHttpHandle() { if (h) WinHttpCloseHandle(h); }
    WinHttpHandle(const WinHttpHandle&) = delete;
    WinHttpHandle& operator=(const WinHttpHandle&) = delete;
    WinHttpHandle(WinHttpHandle&& o) noexcept : h(o.h) { o.h = nullptr; }
    WinHttpHandle& operator=(WinHttpHandle&& o) noexcept {
        if (this != &o) {
            if (h) WinHttpCloseHandle(h);
            h = o.h; o.h = nullptr;
        }
        return *this;
    }
    operator HINTERNET() const { return h; }
};

struct ParsedUrl {
    std::wstring host;
    std::wstring path;
    INTERNET_PORT port{0};
    bool https{false};
};

static bool CrackUrl(const std::wstring& url, ParsedUrl& out) {
    URL_COMPONENTS uc{};
    wchar_t host[512]{};
    wchar_t path[2048]{};
    uc.dwStructSize = sizeof(uc);
    uc.lpszHostName = host; uc.dwHostNameLength = ARRAYSIZE(host);
    uc.lpszUrlPath = path; uc.dwUrlPathLength = ARRAYSIZE(path);
    uc.dwSchemeLength = (DWORD)-1;

    if (!WinHttpCrackUrl(url.c_str(), 0, 0, &uc)) {
        std::wcerr << L"WinHttpCrackUrl failed: " << FormatLastError() << L"\n";
        return false;
    }
    out.host.assign(uc.lpszHostName, uc.dwHostNameLength);
    out.path.clear();
    if (uc.lpszUrlPath && uc.dwUrlPathLength) out.path.append(uc.lpszUrlPath, uc.dwUrlPathLength);
    if (uc.lpszExtraInfo && uc.dwExtraInfoLength) out.path.append(uc.lpszExtraInfo, uc.dwExtraInfoLength);
    out.port = uc.nPort;
    out.https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    if (out.path.empty()) out.path = L"/";
    return true;
}

static bool HttpRequest(const std::wstring& method,
                        const std::wstring& url,
                        const std::string& body,
                        std::string& out_body,
                        std::map<std::wstring, std::wstring> extra_headers = {}) {
    out_body.clear();
    ParsedUrl u{};
    if (!CrackUrl(url, u)) return false;

    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP Client/1.0",
                                       WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME,
                                       WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) {
        std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n";
        return false;
    }

    WinHttpHandle hConnect(WinHttpConnect(hSession, u.host.c_str(), u.port, 0));
    if (!hConnect) {
        std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n";
        return false;
    }

    DWORD flags = u.https ? WINHTTP_FLAG_SECURE : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), u.path.c_str(),
                                              nullptr, WINHTTP_NO_REFERER,
                                              WINHTTP_DEFAULT_ACCEPT_TYPES,
                                              flags));
    if (!hRequest) {
        std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n";
        return false;
    }

    std::wstringstream hdrs;
    hdrs << L"User-Agent: WinHTTP Tor-Scaffold/1.0\r\n";
    if (method == L"POST") {
        hdrs << L"Content-Type: application/x-www-form-urlencoded\r\n";
    }
    for (auto& kv : extra_headers) {
        hdrs << kv.first << L": " << kv.second << L"\r\n";
    }

    if (!WinHttpAddRequestHeaders(hRequest, hdrs.str().c_str(), (DWORD)-1L, WINHTTP_ADDREQ_FLAG_ADD)) {
        std::wcerr << L"WinHttpAddRequestHeaders failed: " << FormatLastError() << L"\n";
        return false;
    }

    BOOL sent = WinHttpSendRequest(hRequest,
                                   WINHTTP_NO_ADDITIONAL_HEADERS,
                                   0,
                                   (LPVOID)(body.empty() ? nullptr : body.data()),
                                   (DWORD)body.size(),
                                   (DWORD)body.size(),
                                   0);
    if (!sent) {
        std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n";
        return false;
    }

    if (!WinHttpReceiveResponse(hRequest, nullptr)) {
        std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n";
        return false;
    }

    DWORD status = 0; DWORD len = sizeof(status);
    if (WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &status, &len, WINHTTP_NO_HEADER_INDEX)) {
        if (status >= 400) {
            std::wcerr << L"HTTP error status: " << status << L"\n";
        }
    }

    std::string buf;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) {
            std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n";
            return false;
        }
        if (!avail) break;
        buf.resize(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, &buf[0], avail, &read)) {
            std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n";
            return false;
        }
        out_body.append(buf.data(), read);
    }
    return true;
}

static bool HttpGet(const std::wstring& url, std::string& out_body) {
    return HttpRequest(L"GET", url, std::string(), out_body);
}

static bool HttpPost(const std::wstring& url, const std::string& body, std::string& out_body) {
    return HttpRequest(L"POST", url, body, out_body);
}

