// -------------------- Minimal consensus parser (plaintext fields) --------------------
struct RelayEntry {
    std::string nickname;
    std::string identity;
    std::string address;
    int or_port{0};
};

struct ConsensusSummary {
    std::string valid_after;
    std::string fresh_until;
    std::string valid_until;
    std::vector<RelayEntry> relays;
};

static ConsensusSummary ParseConsensus(const std::string& text) {
    ConsensusSummary cs;
    std::istringstream iss(text);
    std::string line;
    RelayEntry cur;
    while (std::getline(iss, line)) {
        if (line.rfind("valid-after ", 0) == 0) cs.valid_after = line.substr(12);
        else if (line.rfind("fresh-until ", 0) == 0) cs.fresh_until = line.substr(12);
        else if (line.rfind("valid-until ", 0) == 0) cs.valid_until = line.substr(12);
        else if (line.rfind("r ", 0) == 0) {
            // r Nickname Identity Digest Published IP ORPort DirPort
            std::istringstream rl(line);
            std::string rtag; rl >> rtag;
            std::string nickname, identity_b64, digest_b64, pub_ts, ip;
            int orport = 0, dirport = 0;
            rl >> nickname >> identity_b64 >> digest_b64 >> pub_ts >> ip >> orport >> dirport;
            cur = RelayEntry{};
            cur.nickname = nickname;
            cur.identity = identity_b64;
            cur.address = ip;
            cur.or_port = orport;
            cs.relays.push_back(cur);
        }
    }
    return cs;
}

// -------------------- Minimal HS descriptor parser (plaintext fields) --------------------
struct HSDescriptorInfo {
    std::string hs_type;
    std::string descriptor_id;
    std::string revision_counter;
    std::vector<std::string> intro_points;
};

static HSDescriptorInfo ParseHSDescriptor(const std::string& text) {
    HSDescriptorInfo d;
    std::istringstream iss(text);
    std::string line;
    while (std::getline(iss, line)) {
        if (line.rfind("hs-descriptor ", 0) == 0) d.hs_type = line.substr(13);
        else if (line.rfind("descriptor-id ", 0) == 0) d.descriptor_id = line.substr(14);
        else if (line.rfind("revision-counter ", 0) == 0) d.revision_counter = line.substr(17);
        else if (line.rfind("introduction-point ", 0) == 0) d.intro_points.push_back(line.substr(19));
    }
    return d;
}

// -------------------- Onion address checker (base32 -> ed25519 pubkey) --------------------
static int b32val(int c) {
    if (c >= 'a' && c <= 'z') return c - 'a';
    if (c >= '2' && c <= '7') return 26 + (c - '2');
    return -1;
}

static bool Base32Decode(const std::string& in, std::vector<uint8_t>& out) {
    int buffer = 0, bitsleft = 0;
    out.clear();
    for (char ch : in) {
        if (ch == '=') break;
        int v = b32val(std::tolower((unsigned char)ch));
        if (v < 0) continue;
        buffer <<= 5; buffer |= v; bitsleft += 5;
        if (bitsleft >= 8) {
            bitsleft -= 8;
            out.push_back((uint8_t)((buffer >> bitsleft) & 0xFF));
        }
    }
    return true;
}

static bool DecodeOnionV3(const std::string& onion, std::array<uint8_t, 32>& pubkey) {
    std::string name = onion;
    auto pos = name.rfind(".onion");
    if (pos != std::string::npos) name = name.substr(0, pos);
    if (name.size() != 56) return false;
    std::vector<uint8_t> dec;
    if (!Base32Decode(name, dec)) return false;
    if (dec.size() != 35) return false; // 32 pubkey + 2 checksum + 1 version
    std::copy(dec.begin(), dec.begin() + 32, pubkey.begin());
    return true;
}

// -------------------- CLI --------------------
static void PrintConsensusSummary(const ConsensusSummary& cs) {
    std::cout << "Consensus valid-after: " << cs.valid_after << "\n";
    std::cout << "fresh-until: " << cs.fresh_until << "\n";
    std::cout << "valid-until: " << cs.valid_until << "\n";
    std::cout << "Relays parsed: " << cs.relays.size() << "\n";
    for (size_t i = 0; i < std::min<size_t>(cs.relays.size(), 5); ++i) {
        const auto& r = cs.relays[i];
        std::cout << "  - " << r.nickname << " " << r.address << ":" << r.or_port << " id=" << r.identity << "\n";
    }
}

static void PrintHSDescriptor(const HSDescriptorInfo& d) {
    std::cout << "hs-descriptor: " << d.hs_type << "\n";
    std::cout << "descriptor-id: " << d.descriptor_id << "\n";
    std::cout << "revision-counter: " << d.revision_counter << "\n";
    std::cout << "introduction-points: " << d.intro_points.size() << "\n";
    for (auto& ip : d.intro_points) std::cout << "  - " << ip << "\n";
}

int wmain(int argc, wchar_t** argv) {
    OpenSSLInit openssl_guard;

    std::map<std::wstring, std::wstring> args;
    for (int i = 1; i < argc; ++i) {
        std::wstring k = argv[i];
        if (k.rfind(L"--", 0) == 0) {
            if (i + 1 < argc && std::wstring(argv[i + 1]).rfind(L"--", 0) != 0) {
                args[k] = argv[++i];
            } else {
                args[k] = L"";
            }
        }
    }

    if (args.count(L"--get")) {
        std::string body;
        if (!HttpGet(args[L"--get"], body)) return 1;
        std::cout << body << std::endl;
        return 0;
    }
    if (args.count(L"--post")) {
        std::wstring url = args[L"--post"]; std::string bodyIn;
        if (args.count(L"--data")) bodyIn = WideToUtf8(args[L"--data"]);
        else if (argc >= 3) bodyIn = WideToUtf8(argv[argc - 1]);
        std::string bodyOut;
        if (!HttpPost(url, bodyIn, bodyOut)) return 1;
        std::cout << bodyOut << std::endl;
        return 0;
    }
    if (args.count(L"--consensus-url")) {
        std::string text;
        if (!HttpGet(args[L"--consensus-url"], text)) return 1;
        auto cs = ParseConsensus(text);
        PrintConsensusSummary(cs);
        return 0;
    }
    if (args.count(L"--descriptor-url")) {
        std::string text;
        if (!HttpGet(args[L"--descriptor-url"], text)) return 1;
        auto d = ParseHSDescriptor(text);
        PrintHSDescriptor(d);
        return 0;
    }
    if (args.count(L"--onion-check")) {
        std::string onion = WideToUtf8(args[L"--onion-check"]);
        std::array<uint8_t, 32> pk{};
        if (!DecodeOnionV3(onion, pk)) {
            std::cerr << "Invalid v3 onion name" << std::endl;
            return 1;
        }
        std::cout << "v3 pubkey: ";
        for (auto b : pk) std::cout << std::hex << std::setw(2) << std::setfill('0') << (int)b;
        std::cout << std::dec << "\n";
        return 0;
    }

    std::cout << "Usage:\n"
                 "  --consensus-url <https_url>       Download and parse consensus\n"
                 "  --descriptor-url <https_url>      Download and parse v3 descriptor\n"
                 "  --get <url>                        HTTP(S) GET\n"
                 "  --post <url> [--data <body>]       HTTP(S) POST\n"
                 "  --onion-check <v3_onion>           Decode/validate v3 onion base32\n";
    return 0;
}

