// UTF conversions
static std::wstring Utf8ToWide(const std::string& s){ if(s.empty()) return L""; int len=MultiByteToWideChar(CP_UTF8,0,s.c_str(),(int)s.size(),nullptr,0); std::wstring out(len,0); MultiByteToWideChar(CP_UTF8,0,s.c_str(),(int)s.size(),&out[0],len); return out; }
static std::string WideToUtf8(const std::wstring& ws){ if(ws.empty()) return ""; int len=WideCharToMultiByte(CP_UTF8,0,ws.c_str(),(int)ws.size(),nullptr,0,nullptr,nullptr); std::string out(len,0); WideCharToMultiByte(CP_UTF8,0,ws.c_str(),(int)ws.size(),&out[0],len,nullptr,nullptr); return out; }

// Error helpers
static std::wstring FormatWinHttpError(DWORD err){ LPWSTR buf=nullptr; DWORD len=FormatMessageW(FORMAT_MESSAGE_FROM_HMODULE|FORMAT_MESSAGE_ALLOCATE_BUFFER|FORMAT_MESSAGE_IGNORE_INSERTS, GetModuleHandleW(L"winhttp.dll"), err, 0, (LPWSTR)&buf, 0, nullptr); std::wstring s=(len&&buf)?std::wstring(buf,len):L"(unknown WinHTTP error)"; if(buf) LocalFree(buf); return s; }
static std::wstring FormatLastError(){ DWORD err=GetLastError(); LPWSTR buf=nullptr; DWORD len=FormatMessageW(FORMAT_MESSAGE_FROM_SYSTEM|FORMAT_MESSAGE_ALLOCATE_BUFFER|FORMAT_MESSAGE_IGNORE_INSERTS, nullptr, err, 0, (LPWSTR)&buf, 0, nullptr); std::wstring s=(len&&buf)?std::wstring(buf,len):L"(unknown error)"; if(buf) LocalFree(buf); return s; }

// RAII handle
struct WinHttpHandle{ HINTERNET h{nullptr}; WinHttpHandle()=default; explicit WinHttpHandle(HINTERNET x):h(x){} ~WinHttpHandle(){ if(h) WinHttpCloseHandle(h);} WinHttpHandle(const WinHttpHandle&)=delete; WinHttpHandle& operator=(const WinHttpHandle&)=delete; WinHttpHandle(WinHttpHandle&&o)noexcept:h(o.h){o.h=nullptr;} WinHttpHandle& operator=(WinHttpHandle&&o)noexcept{ if(this!=&o){ if(h) WinHttpCloseHandle(h); h=o.h; o.h=nullptr;} return *this;} operator HINTERNET()const{return h;} };

// OpenSSL helpers
struct OpenSSLInit{ OpenSSLInit(){ OPENSSL_init_crypto(OPENSSL_INIT_LOAD_CONFIG, nullptr);} ~OpenSSLInit(){ /* OpenSSL 3 auto-cleans */ } };

static bool EVP_SHA3_256(const std::vector<unsigned char>& in, std::array<unsigned char,32>& out){ EVP_MD_CTX* ctx = EVP_MD_CTX_new(); if(!ctx) return false; bool ok=false; do{ const EVP_MD* md = EVP_sha3_256(); if(!md) break; if(EVP_DigestInit_ex(ctx, md, nullptr)!=1) break; if(!in.empty() && EVP_DigestUpdate(ctx, in.data(), in.size())!=1) break; unsigned int len=0; if(EVP_DigestFinal_ex(ctx, out.data(), &len)!=1) break; ok = (len==out.size()); }while(false); EVP_MD_CTX_free(ctx); return ok; }

// Base32 (RFC4648, lowercase, no padding) for .onion
static int b32val(int c){ if(c>='a'&&c<='z') return c-'a'; if(c>='2'&&c<='7') return 26+(c-'2'); return -1; }
static bool Base32NoPadDecodeLower(const std::string& in, std::vector<unsigned char>& out){ out.clear(); int buffer=0, bits=0; for(unsigned char uc: in){ int v=b32val(std::tolower(uc)); if(v<0) return false; buffer=(buffer<<5)|v; bits+=5; if(bits>=8){ bits-=8; out.push_back((unsigned char)((buffer>>bits)&0xFF)); } } if(bits!=0){ // leftover bits must be zero
 if((buffer & ((1<<bits)-1))!=0) return false; }
 return true; }

// Onion v3 check using OpenSSL SHA3-256
static bool ValidateOnionV3(const std::string& onion){ std::string host=onion; if(host.rfind(".onion", host.size()-6)!=std::string::npos){ host = host.substr(0, host.size()-6); } if(host.size()!=56) return false; for(char c: host){ char lc=(char)std::tolower((unsigned char)c); if(!((lc>='a'&&lc<='z')||(lc>='2'&&lc<='7'))) return false; }
 std::vector<unsigned char> dec; if(!Base32NoPadDecodeLower(host, dec)) return false; if(dec.size()!=35) return false; // 32 pubkey + 2 checksum + 1 version
 unsigned char ver = dec[34]; if(ver!=0x03) return false;
 std::array<unsigned char,32> digest{}; std::vector<unsigned char> pre; pre.reserve(32+15+1);
 pre.insert(pre.end(), dec.begin(), dec.begin()+32); // pubkey
 static const unsigned char tag[] = {0x6f,0x6e,0x69,0x6f,0x6e,0x20,0x76,0x33,0x20,0x63,0x68,0x65,0x63,0x6b,0x73,0x75,0x6d}; // "onion v3 checksum"
 pre.insert(pre.end(), tag, tag+15+2); // Actually 15 chars + 2? Correct tag is 15 bytes; fix below
 // Correct tag bytes for "onion checksum": per spec "onion checksum" with space and v3
 // We'll rebuild pre correctly:
 pre.clear();
 const char* tagstr = "onion v3 checksum"; pre.insert(pre.end(), tagstr, tagstr+17);
 pre.insert(pre.end(), dec.begin(), dec.begin()+32); // pubkey
 pre.push_back(0x03);
 if(!EVP_SHA3_256(pre, digest)) return false;
 // compare first two bytes of digest to checksum
 if(digest[0]!=dec[32] || digest[1]!=dec[33]) return false; return true; }

// URL parsing
struct ParsedUrl{ std::wstring host; std::wstring path; INTERNET_PORT port{0}; bool https{false}; };
static bool CrackUrl(const std::wstring& url, ParsedUrl& out){ URL_COMPONENTS uc{}; wchar_t host[512]{}; wchar_t path[4096]{}; uc.dwStructSize=sizeof(uc); uc.lpszHostName=host; uc.dwHostNameLength=ARRAYSIZE(host); uc.lpszUrlPath=path; uc.dwUrlPathLength=ARRAYSIZE(path); uc.dwSchemeLength=(DWORD)-1; if(!WinHttpCrackUrl(url.c_str(),0,0,&uc)){ std::wcerr<<L"WinHttpCrackUrl failed: "<<FormatLastError()<<L"\n"; return false;} out.host.assign(uc.lpszHostName, uc.dwHostNameLength); out.path.clear(); if(uc.lpszUrlPath && uc.dwUrlPathLength) out.path.append(uc.lpszUrlPath, uc.dwUrlPathLength); if(uc.lpszExtraInfo && uc.dwExtraInfoLength) out.path.append(uc.lpszExtraInfo, uc.dwExtraInfoLength); if(out.path.empty()) out.path=L"/"; out.port = uc.nPort; out.https = (uc.nScheme==INTERNET_SCHEME_HTTPS); return true; }

// WinHTTP GET/POST with optional SOCKS proxy (Windows 10 1709+ supports socks=)
static bool HttpRequest(const std::wstring& url, const std::wstring& method, const std::wstring& proxy, const std::string* body, std::string& out){ out.clear(); ParsedUrl pu{}; if(!CrackUrl(url, pu)) return false; WinHttpHandle hSession(WinHttpOpen(L"TorWinHttpClient/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0)); if(!hSession){ std::wcerr<<L"WinHttpOpen failed: "<<FormatLastError()<<L"\n"; return false; }
 if(!proxy.empty()){
 DWORD opt=WINHTTP_ACCESS_TYPE_NAMED_PROXY; if(!WinHttpSetOption(hSession, WINHTTP_OPTION_ACCESS_TYPE, &opt, sizeof(opt))){ std::wcerr<<L"Set access type failed: "<<FormatLastError()<<L"\n"; return false; }
 WINHTTP_PROXY_INFO pi{}; pi.dwAccessType=WINHTTP_ACCESS_TYPE_NAMED_PROXY; std::wstring proxyStr = proxy; // e.g., L"socks=127.0.0.1:9050"
 pi.lpszProxy = (LPWSTR)proxyStr.c_str(); if(!WinHttpSetOption(hSession, WINHTTP_OPTION_PROXY, &pi, sizeof(pi))){ std::wcerr<<L"WINHTTP_OPTION_PROXY failed: "<<FormatLastError()<<L"\n"; /* continue; some builds require WINHTTP_OPTION_PROXY_USERNAME/PASSWORD if set */ }
 }
 WinHttpHandle hConnect(WinHttpConnect(hSession, pu.host.c_str(), pu.port?pu.port:(pu.https?443:80), 0)); if(!hConnect){ std::wcerr<<L"WinHttpConnect failed: "<<FormatLastError()<<L"\n"; return false; }
 DWORD flags = pu.https ? WINHTTP_FLAG_SECURE : 0; WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), pu.path.c_str(), nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags)); if(!hRequest){ std::wcerr<<L"WinHttpOpenRequest failed: "<<FormatLastError()<<L"\n"; return false; }
 // For .onion over HTTPS, disable certain checks (many onion sites use self-signed/invalid certs)
 if(pu.https){ DWORD secFlags = SECURITY_FLAG_IGNORE_UNKNOWN_CA | SECURITY_FLAG_IGNORE_CERT_CN_INVALID | SECURITY_FLAG_IGNORE_CERT_DATE_INVALID | SECURITY_FLAG_IGNORE_REVOCATION; WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &secFlags, sizeof(secFlags)); }
 // Send
 BOOL bres=FALSE; if(body){ std::wstring headers=L"Content-Type: application/x-www-form-urlencoded\r\n"; bres = WinHttpSendRequest(hRequest, headers.c_str(), (DWORD)-1, (LPVOID)body->data(), (DWORD)body->size(), (DWORD)body->size(), 0); }
 else{ bres = WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0); }
 if(!bres){ std::wcerr<<L"WinHttpSendRequest failed: "<<FormatLastError()<<L"\n"; return false; }
 if(!WinHttpReceiveResponse(hRequest, nullptr)){ std::wcerr<<L"WinHttpReceiveResponse failed: "<<FormatLastError()<<L"\n"; return false; }
 // Read response
 DWORD dwSize=0; do{ if(!WinHttpQueryDataAvailable(hRequest, &dwSize)){ std::wcerr<<L"WinHttpQueryDataAvailable failed: "<<FormatLastError()<<L"\n"; return false; } if(dwSize==0) break; std::string buf; buf.resize(dwSize); DWORD dwRead=0; if(!WinHttpReadData(hRequest, &buf[0], dwSize, &dwRead)){ std::wcerr<<L"WinHttpReadData failed: "<<FormatLastError()<<L"\n"; return false; } buf.resize(dwRead); out.append(buf); }while(dwSize>0);
 return true; }

// Minimal Tor consensus parsing: extract 'valid-after', 'fresh-until', 'vote-digest' and 'r'/"s" entries
struct Relay{ std::string nick; std::string fp; std::string address; int orport{0}; };
struct Consensus{ std::string valid_after; std::string fresh_until; std::vector<Relay> relays; };

static void ParseConsensus(const std::string& text, Consensus& c){ std::istringstream iss(text); std::string line; Relay cur{}; bool inRouter=false; while(std::getline(iss,line)){ if(line.rfind("valid-after ",0)==0){ c.valid_after=line.substr(12); }
 else if(line.rfind("fresh-until ",0)==0){ c.fresh_until=line.substr(12); }
 else if(!line.empty() && line[0]=='r' && line.size()>2 && line[1]==' '){ // r line: r Nickname Identity Digest IP ORPort DirPort
 std::istringstream ls(line); char rch; ls>>rch; Relay r{}; ls>>r.nick>>r.fp; std::string digest; ls>>digest>>r.address>>r.orport; if(!r.nick.empty()) c.relays.push_back(r); inRouter=true; cur=r; }
 else if(inRouter && !line.empty() && line[0]=='s' && (line.size()==1||line[1]==' ')){ inRouter=false; }
 }
}

// Simple v3 descriptor parse: capture key-value headers and base64 blocks
struct HSDescriptor{ std::map<std::string,std::string> headers; std::map<std::string,std::string> blocks; };
static void ParseHSDescriptor(const std::string& txt, HSDescriptor& d){ std::istringstream iss(txt); std::string line; std::string curBlockName; std::ostringstream curBlock; auto flush=[&](){ if(!curBlockName.empty()){ d.blocks[curBlockName]=curBlock.str(); curBlockName.clear(); curBlock.str(""); curBlock.clear(); } }; while(std::getline(iss,line)){ if(line.rfind("-----BEGIN ",0)==0){ flush(); size_t end=line.find("-----",11); if(end!=std::string::npos){ curBlockName=line.substr(11, end-11); } }
 else if(line.rfind("-----END ",0)==0){ flush(); }
 else if(!curBlockName.empty()){ if(!line.empty()) curBlock<<line<<"\n"; }
 else{ // header lines like: hs-descriptor 3
 size_t sp=line.find(' '); if(sp!=std::string::npos){ std::string k=line.substr(0,sp); std::string v=line.substr(sp+1); d.headers[k]=v; } }
 }
 flush(); }

// Helper to GET a URL
static bool HttpGet(const std::wstring& url, const std::wstring& proxy, std::string& out){ return HttpRequest(url, L"GET", proxy, nullptr, out); }
static bool HttpPost(const std::wstring& url, const std::wstring& proxy, const std::string& data, std::string& out){ return HttpRequest(url, L"POST", proxy, &data, out); }

static void PrintConsensusSummary(const Consensus& c){ std::cout<<"Consensus valid-after: "<<c.valid_after<<"\n"; std::cout<<"Consensus fresh-until: "<<c.fresh_until<<"\n"; std::cout<<"Relays parsed: "<<c.relays.size()<<"\n"; for(size_t i=0;i<std::min<size_t>(c.relays.size(),5);++i){ const auto& r=c.relays[i]; std::cout<<"  - "<<r.nick<<" "<<r.address<<":"<<r.orport<<" fp="<<r.fp<<"\n"; } }

static void PrintDescriptorSummary(const HSDescriptor& d){ std::cout<<"Descriptor headers: "<<d.headers.size()<<"\n"; for(const auto& kv: d.headers){ std::cout<<"  "<<kv.first<<": "<<kv.second<<"\n"; } std::cout<<"Blocks: "<<d.blocks.size()<<"\n"; for(const auto& kv: d.blocks){ std::cout<<"  ["<<kv.first<<"] size="<<kv.second.size()<<" bytes (base64 text)\n"; } }

int wmain(int argc, wchar_t** argv){ OpenSSLInit openssl_guard; std::wstring socksProxy; std::wstring getUrl; std::wstring postUrl; std::string postData; std::wstring consensusUrl; std::wstring descriptorUrl; std::wstring onionToGet; std::wstring onionToPost; std::string onionPostData;
 for(int i=1;i<argc;i++){
     std::wstring a=argv[i];
     if(a==L"--socks" && i+1<argc){ socksProxy = argv[++i]; /* e.g., L"socks=127.0.0.1:9050" */ }
     else if(a==L"--get" && i+1<argc){ getUrl = argv[++i]; }
     else if(a==L"--post" && i+2<argc){ postUrl = argv[++i]; postData = WideToUtf8(argv[++i]); }
     else if(a==L"--consensus-url" && i+1<argc){ consensusUrl = argv[++i]; }
     else if(a==L"--descriptor-url" && i+1<argc){ descriptorUrl = argv[++i]; }
     else if(a==L"--onion-get" && i+1<argc){ onionToGet = argv[++i]; }
     else if(a==L"--onion-post" && i+2<argc){ onionToPost = argv[++i]; onionPostData = WideToUtf8(argv[++i]); }
 }
 if(!getUrl.empty()){
     std::string body; if(!HttpGet(getUrl, socksProxy, body)){ std::wcerr<<L"GET failed\n"; return 1;} std::cout<<"GET body size: "<<body.size()<<"\n"; }
 if(!postUrl.empty()){
     std::string body; if(!HttpPost(postUrl, socksProxy, postData, body)){ std::wcerr<<L"POST failed\n"; return 1;} std::cout<<"POST body size: "<<body.size()<<"\n"; }
 if(!consensusUrl.empty()){
     std::string txt; if(!HttpGet(consensusUrl, socksProxy, txt)){ std::wcerr<<L"Consensus download failed\n"; return 1;} Consensus c{}; ParseConsensus(txt, c); PrintConsensusSummary(c);
 }
 if(!descriptorUrl.empty()){
     std::string txt; if(!HttpGet(descriptorUrl, socksProxy, txt)){ std::wcerr<<L"Descriptor download failed\n"; return 1;} HSDescriptor d{}; ParseHSDescriptor(txt, d); PrintDescriptorSummary(d);
 }
 if(!onionToGet.empty()){
     // Validate onion hostname (optional but recommended)
     std::wstring hostW; ParsedUrl pu{}; if(CrackUrl(onionToGet, pu)){ hostW=pu.host; } else { hostW=onionToGet; }
     std::string host = WideToUtf8(hostW); std::string bare = host; auto pos = bare.find(":" ); if(pos!=std::string::npos) bare = bare.substr(0,pos); if(bare.rfind(".onion")!=std::string::npos){ std::string name = bare.substr(0, bare.size()-6); if(name.size()==56){ bool ok=ValidateOnionV3(name+".onion"); (void)ok; }
     }
     std::string body; if(!HttpGet(onionToGet, socksProxy, body)){ std::wcerr<<L"Onion GET failed\n"; return 1;} std::cout<<"Onion GET body size: "<<body.size()<<"\n"; }
 if(!onionToPost.empty()){
     std::string body; if(!HttpPost(onionToPost, socksProxy, onionPostData, body)){ std::wcerr<<L"Onion POST failed\n"; return 1;} std::cout<<"Onion POST body size: "<<body.size()<<"\n"; }
 std::cout<<"Done."<<std::endl; return 0; }

//+------------------------------------------------------------------+
//|                                       EMA_RSI_ATR_Manager.mq5    |
//|   EMA Cross + RSI + ATR with robust risk & margin management     |
//|   One-position-per-symbol, spread/session filters, trailing SL   |
//+------------------------------------------------------------------+
#property strict
#property version   "1.20"
#property description "EMA Cross + RSI + ATR strategy with complete trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct          = 0.5;   // Percent of equity to risk per trade
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Do not open if current margin level below this (%); ignored if <=0 or margin level unavailable
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastClosedBarTime = 0;

// Symbol parameters cache
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC)
bool    gSkipHour[24];

// Cached symbol
string  gSymbol;

//----------------------------------------------
// Utility: Parse skip hours string to bool map
//----------------------------------------------
void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

//----------------------------------------------
// Utility: Refresh and cache symbol trading info
//----------------------------------------------
bool RefreshSymbolInfo(const string sym)
{
  gPoint = SymbolInfoDouble(sym, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(sym, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE);
  gTickValue = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN);
  gMaxVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX);
  gVolStep = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_FREEZE_LEVEL);

  if(gPoint<=0 || gTickSize<=0 || gTickValue<=0 || gMinVolume<=0 || gVolStep<=0)
  {
    PrintFormat("Symbol info invalid: point=%.10f ticksize=%.10f tickvalue=%.10f minvol=%.2f volstep=%.2f",
                gPoint, gTickSize, gTickValue, gMinVolume, gVolStep);
    return false;
  }
  return true;
}

//----------------------------------------------
// Utility: Normalize lot volume to broker step
//----------------------------------------------
double NormalizeVolume(double vol)
{
  if(vol<=0) return 0.0;
  double steps = MathFloor(vol / gVolStep + 1e-8);
  double v = steps * gVolStep;
  if(v < gMinVolume) v = 0.0;
  if(v > gMaxVolume) v = gMaxVolume;
  return NormalizeDouble(v, (int)MathMax(0, (int)MathRound(-MathLog10(gVolStep))));
}

//----------------------------------------------
// Utility: Normalize price to symbol digits
//----------------------------------------------
double NormalizePrice(double price)
{
  return NormalizeDouble(price, gDigits);
}

//----------------------------------------------
// Utility: Check any open position exists for this symbol (any magic)
//----------------------------------------------
bool HasAnyPositionOnSymbol(const string sym)
{
  for(int i=0;i<PositionsTotal();i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) == sym)
      return true;
  }
  return false;
}

//----------------------------------------------
// Utility: Find our (magic) position on this symbol
//----------------------------------------------
bool GetOurPosition(const string sym, ulong &ticketOut, long &typeOut, double &priceOpenOut, double &slOut, double &tpOut, double &volumeOut)
{
  ticketOut = 0; typeOut = -1; slOut = 0; tpOut=0; volumeOut=0; priceOpenOut=0;
  for(int i=0;i<PositionsTotal();i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) != sym) continue;
    if((ulong)PositionGetInteger(POSITION_MAGIC) != InpMagicNumber) continue;

    ticketOut = (ulong)PositionGetInteger(POSITION_TICKET);
    typeOut   = (long)PositionGetInteger(POSITION_TYPE);
    priceOpenOut = PositionGetDouble(POSITION_PRICE_OPEN);
    slOut = PositionGetDouble(POSITION_SL);
    tpOut = PositionGetDouble(POSITION_TP);
    volumeOut = PositionGetDouble(POSITION_VOLUME);
    return true;
  }
  return false;
}

//----------------------------------------------
// Utility: Get margin level percent (returns -1 if unavailable)
//----------------------------------------------
double GetMarginLevelPct()
{
  double margin = AccountInfoDouble(ACCOUNT_MARGIN);
  if(margin<=0) return -1.0;
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  return (equity/margin)*100.0;
}

//----------------------------------------------
// Utility: Calculate volume by risk (equity-based) and margin caps
//----------------------------------------------
double CalcVolumeByRisk(const string sym, const bool isBuy, const double entry, const double stop)
{
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(equity<=0 || freeMargin<=0) { Print("Equity/free margin invalid"); return 0.0; }

  // Risk per trade in account currency
  double riskAmt = equity * (InpRiskPerTradePct/100.0);
  if(riskAmt<=0) { Print("Computed risk amount <= 0"); return 0.0; }

  double slDistance = MathAbs(entry - stop);
  if(slDistance < gPoint* (gStopsLevelPoints+1))
  {
    PrintFormat("SL distance too small: %.10f", slDistance);
    return 0.0;
  }

  // Value per point per 1 lot in account currency
  double pointsPerPrice = 1.0 / gPoint;
  double pointValuePerLot;
  if(!SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE, pointValuePerLot) || pointValuePerLot<=0)
    pointValuePerLot = gTickValue;
  double lossPerLot = (slDistance / gPoint) * pointValuePerLot;
  if(lossPerLot<=0) { Print("Loss per lot computed <=0"); return 0.0; }

  double lotsByRisk = riskAmt / lossPerLot;

  // Check margin per lot using OrderCalcMargin
  double marginPerLot = 0.0;
  ENUM_ORDER_TYPE ot = isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  if(!OrderCalcMargin(ot, sym, 1.0, entry, marginPerLot))
  {
    Print("OrderCalcMargin failed. LastError=", GetLastError());
    return 0.0;
  }
  if(marginPerLot<=0) { Print("Margin per lot <= 0"); return 0.0; }

  // Cap by free margin usage
  double maxMarginUsage = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
  double lotsByMargin = maxMarginUsage / marginPerLot;

  double lots = MathMin(lotsByRisk, lotsByMargin);
  lots = NormalizeVolume(lots);
  return lots;
}

//----------------------------------------------
// Utility: Spread and session filters
//----------------------------------------------
bool PassFilters(const string sym)
{
  // Spread filter
  double spreadPoints = (SymbolInfoDouble(sym, SYMBOL_ASK) - SymbolInfoDouble(sym, SYMBOL_BID)) / gPoint;
  if(InpMaxSpreadPoints>0 && spreadPoints > InpMaxSpreadPoints)
  {
    PrintFormat("Spread too high: %.1f pts > max %d", spreadPoints, InpMaxSpreadPoints);
    return false;
  }
  // Session filter (UTC hours)
  datetime t = TimeCurrent();
  MqlDateTime dt; TimeToStruct(t, dt);
  if(dt.hour>=0 && dt.hour<24 && gSkipHour[dt.hour])
    return false;

  return true;
}

//----------------------------------------------
// Indicator setup
//----------------------------------------------
bool SetupIndicators(const string sym)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);

  hFastEMA = iMA(sym, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(sym, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(sym, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(sym, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("Failed to create indicators. Err=", GetLastError());
    return false;
  }
  return true;
}

//----------------------------------------------
// Read indicator values on last closed candle
//----------------------------------------------
bool ReadSignals(const string sym, double &emaFastPrev, double &emaFastCurr, double &emaSlowPrev, double &emaSlowCurr, double &rsiPrev, double &rsiCurr, double &atrCurr)
{
  if(BarsCalculated(hFastEMA)<3 || BarsCalculated(hSlowEMA)<3 || BarsCalculated(hRSI)<3 || BarsCalculated(hATR)<3)
    return false;

  int shiftCurr = 1; // last closed bar
  int shiftPrev = 2;

  double buf[3];
  if(CopyBuffer(hFastEMA,0,shiftPrev,2,buf)!=2) return false; emaFastPrev=buf[1]; emaFastCurr=buf[0];
  if(CopyBuffer(hSlowEMA,0,shiftPrev,2,buf)!=2) return false; emaSlowPrev=buf[1]; emaSlowCurr=buf[0];
  if(CopyBuffer(hRSI,0,shiftPrev,2,buf)!=2) return false; rsiPrev=buf[1]; rsiCurr=buf[0];
  if(CopyBuffer(hATR,0,shiftCurr,1,buf)!=1) return false; atrCurr=buf[0];

  return (emaFastPrev!=0 && emaFastCurr!=0 && emaSlowPrev!=0 && emaSlowCurr!=0 && rsiCurr!=0 && atrCurr>0);
}

//----------------------------------------------
// Build SL/TP prices from ATR and RR
//----------------------------------------------
void BuildStops(const bool isBuy, const double entry, const double atr, double &sl, double &tp)
{
  double slDist = atr * InpATR_SL_Mult;
  double tpDist = slDist * InpRR;
  if(isBuy)
  {
    sl = NormalizePrice(entry - slDist);
    tp = NormalizePrice(entry + tpDist);
  }
  else
  {
    sl = NormalizePrice(entry + slDist);
    tp = NormalizePrice(entry - tpDist);
  }
}

//----------------------------------------------
// Place order with validations
//----------------------------------------------
bool PlaceOrder(const string sym, const bool isBuy, const double entry, const double sl, const double tp, const double lots)
{
  if(lots <= 0) { Print("PlaceOrder: lots <= 0"); return false; }

  // Check broker stops and freeze levels
  double slDistPts = MathAbs(entry - sl)/gPoint;
  double tpDistPts = MathAbs(tp - entry)/gPoint;
  int minStops = gStopsLevelPoints;
  if(minStops>0)
  {
    if(slDistPts < minStops || tpDistPts < minStops)
    {
      PrintFormat("Stops too close. SLdist=%.1f TPdist=%.1f min=%d", slDistPts, tpDistPts, minStops);
      return false;
    }
  }

  // Margin checks: margin level and prospective margin usage
  double marginLevel = GetMarginLevelPct();
  if(InpMinMarginLevelPct>0 && marginLevel>0 && marginLevel < InpMinMarginLevelPct)
  {
    PrintFormat("Margin level %.1f%% < min %.1f%%", marginLevel, InpMinMarginLevelPct);
    return false;
  }

  double calcMargin=0.0; ENUM_ORDER_TYPE ot = isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL;
  if(!OrderCalcMargin(ot, sym, lots, entry, calcMargin))
  {
    Print("OrderCalcMargin(lots) failed: ", GetLastError());
    return false;
  }

  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(freeMargin<=0) { Print("Free margin invalid"); return false; }

  double maxUsage = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
  if(calcMargin > maxUsage)
  {
    PrintFormat("Per-trade margin %.2f exceeds cap %.2f", calcMargin, maxUsage);
    return false;
  }

  trade.SetExpertMagicNumber(InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool ok = isBuy ? trade.Buy(lots, sym, 0.0, sl, tp, "EMA_RSI_ATR Buy")
                  : trade.Sell(lots, sym, 0.0, sl, tp, "EMA_RSI_ATR Sell");
  if(!ok)
  {
    PrintFormat("Order send failed. RetCode=%d LastError=%d", trade.ResultRetcode(), GetLastError());
    return false;
  }
  else
  {
    PrintFormat("Order opened. Ticket=%I64u Lots=%.2f Price=%.5f SL=%.5f TP=%.5f",
                trade.ResultOrder(), lots, trade.ResultPrice(), sl, tp);
  }
  return true;
}

//----------------------------------------------
// Manage trailing stop and breakeven
//----------------------------------------------
void ManagePosition()
{
  ulong ticket; long type; double open, sl, tp, vol;
  if(!GetOurPosition(gSymbol, ticket, type, open, sl, tp, vol)) return;

  double bid = SymbolInfoDouble(gSymbol, SYMBOL_BID);
  double ask = SymbolInfoDouble(gSymbol, SYMBOL_ASK);
  double price = (type==POSITION_TYPE_BUY)? bid : ask;

  // Trailing using ATR
  if(InpAllowTrailing && hATR!=INVALID_HANDLE)
  {
    double atr; double buf[1];
    if(CopyBuffer(hATR,0,1,1,buf)==1) atr=buf[0]; else atr=0.0;
    if(atr>0)
    {
      double trailDist = InpATR_TrailMult * atr;
      double newSL;
      if(type==POSITION_TYPE_BUY)
      {
        newSL = NormalizePrice(price - trailDist);
        if(newSL > sl && newSL < price - gPoint*(gStopsLevelPoints+1))
          trade.PositionModify(ticket, newSL, tp);
      }
      else
      {
        newSL = NormalizePrice(price + trailDist);
        if((sl==0 || newSL < sl) && newSL > price + gPoint*(gStopsLevelPoints+1))
          trade.PositionModify(ticket, newSL, tp);
      }
    }
  }

  // Breakeven logic
  if(InpBreakevenRR>0 && sl>0)
  {
    double risk = MathAbs(open - sl);
    double rrTarget = risk * InpBreakevenRR;
    double newSL;
    if(type==POSITION_TYPE_BUY)
    {
      if(price - open >= rrTarget)
      {
        newSL = NormalizePrice(open);
        if(newSL > sl) trade.PositionModify(ticket, newSL, tp);
      }
    }
    else
    {
      if(open - price >= rrTarget)
      {
        newSL = NormalizePrice(open);
        if(sl==0 || newSL < sl) trade.PositionModify(ticket, newSL, tp);
      }
    }
  }
}

//+------------------------------------------------------------------+
//| Expert initialization                                            |
//+------------------------------------------------------------------+
int OnInit()
{
  gSymbol = _Symbol;
  ParseSkipHours(InpSkipHoursUTC);
  if(!RefreshSymbolInfo(gSymbol))
  {
    Print("OnInit: RefreshSymbolInfo failed");
    return INIT_FAILED;
  }
  if(!SetupIndicators(gSymbol))
  {
    Print("OnInit: SetupIndicators failed");
    return INIT_FAILED;
  }
  Print("EA initialized on ", gSymbol, " digits=", gDigits, " point=", DoubleToString(gPoint,8));
  return INIT_SUCCEEDED;
}

//+------------------------------------------------------------------+
//| Expert deinitialization                                          |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick()
{
  // Work only on new closed bar for signals, but manage trailing every tick
  ManagePosition();

  // Signal evaluation only on new bar
  MqlRates rates[];
  if(CopyRates(gSymbol, InpTimeframe, 0, 3, rates) < 3) return;
  if(gLastClosedBarTime == rates[1].time) return;
  gLastClosedBarTime = rates[1].time;

  if(!PassFilters(gSymbol)) return;

  double emaFastPrev, emaFastCurr, emaSlowPrev, emaSlowCurr, rsiPrev, rsiCurr, atrCurr;
  if(!ReadSignals(gSymbol, emaFastPrev, emaFastCurr, emaSlowPrev, emaSlowCurr, rsiPrev, rsiCurr, atrCurr)) return;

  if(InpATR_MinFilter>0 && atrCurr < InpATR_MinFilter) return;

  // One-position-per-symbol across all magics
  if(HasAnyPositionOnSymbol(gSymbol)) return;

  double bid = SymbolInfoDouble(gSymbol, SYMBOL_BID);
  double ask = SymbolInfoDouble(gSymbol, SYMBOL_ASK);

  bool buySignal = (emaFastPrev < emaSlowPrev) && (emaFastCurr > emaSlowCurr) && (rsiCurr >= InpRSI_Buy);
  bool sellSignal= (emaFastPrev > emaSlowPrev) && (emaFastCurr < emaSlowCurr) && (rsiCurr <= InpRSI_Sell);

  if(!buySignal && !sellSignal) return;

  bool isBuy = buySignal;
  double entry = isBuy ? ask : bid;
  double sl, tp; BuildStops(isBuy, entry, atrCurr, sl, tp);

  // Pre-check margin level
  double marginLevel = GetMarginLevelPct();
  if(InpMinMarginLevelPct>0 && marginLevel>0 && marginLevel < InpMinMarginLevelPct)
  {
    PrintFormat("OnTick: margin level %.1f%% < min %.1f%%", marginLevel, InpMinMarginLevelPct);
    return;
  }

  double lots = CalcVolumeByRisk(gSymbol, isBuy, entry, sl);
  if(lots<=0)
  {
    Print("OnTick: lots calc returned 0");
    return;
  }

  // Final margin revalidation with computed lots
  double calcMargin=0.0; ENUM_ORDER_TYPE ot = isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL;
  if(!OrderCalcMargin(ot, gSymbol, lots, entry, calcMargin))
  {
    Print("OnTick: OrderCalcMargin final failed: ", GetLastError());
    return;
  }
  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double cap = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
  if(calcMargin>cap)
  {
    PrintFormat("OnTick: final margin %.2f exceeds cap %.2f; aborting", calcMargin, cap);
    return;
  }

  PlaceOrder(gSymbol, isBuy, entry, sl, tp, lots);
}

//+------------------------------------------------------------------+
//|                                         EMA_RSI_ATR_Manager.mq5  |
//|       EMA Cross + RSI + ATR with robust risk & margin controls   |
//|       One-position-per-symbol, spread/session filters, trailing  |
//+------------------------------------------------------------------+
#property strict
#property version   "1.20"
#property description "EMA Cross + RSI + ATR strategy with complete trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct          = 0.5;   // Percent of equity to risk per trade
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Do not open if margin level below this (%); ignored if <=0 or if account doesn't report level
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastClosedBarTime = 0;

// Symbol parameters cache
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC)
bool    gSkipHour[24];

//+------------------------------------------------------------------+
//| Utility: Parse skip hours string to bool map                      |
//+------------------------------------------------------------------+
void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

//+------------------------------------------------------------------+
//| Utility: Refresh and cache symbol trading info                    |
//+------------------------------------------------------------------+
bool RefreshSymbolInfo(const string sym)
{
  if(!SymbolInfoInteger(sym,SYMBOL_SELECT))
    SymbolSelect(sym,true);

  gPoint  = SymbolInfoDouble(sym, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(sym, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE);
  gTickValue= SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume= SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN);
  gMaxVolume= SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX);
  gVolStep  = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints  = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_FREEZE_LEVEL);

  if(gPoint<=0 || gTickSize<=0 || gTickValue<=0 || gMinVolume<=0 || gVolStep<=0)
  {
    PrintFormat("Symbol info invalid: point=%.10f ticksize=%.10f tickvalue=%.10f minvol=%.2f volstep=%.2f",
                gPoint, gTickSize, gTickValue, gMinVolume, gVolStep);
    return false;
  }
  return true;
}

//+------------------------------------------------------------------+
//| Utility: Normalize lot volume to broker step                      |
//+------------------------------------------------------------------+
double NormalizeVolume(double vol)
{
  if(vol<=0) return 0.0;
  double steps = MathFloor(vol / gVolStep + 1e-8);
  double v = steps * gVolStep;
  if(v < gMinVolume) v = 0.0;
  if(v > gMaxVolume) v = gMaxVolume;
  // Normalize to number of decimals implied by vol step
  int volDigits = (int)MathRound(MathLog10(1.0/gVolStep));
  if(volDigits<0) volDigits=0;
  return NormalizeDouble(v, volDigits);
}

//+------------------------------------------------------------------+
//| Utility: Normalize price to symbol digits                         |
//+------------------------------------------------------------------+
double NormalizePrice(double price)
{
  return NormalizeDouble(price, gDigits);
}

//+------------------------------------------------------------------+
//| Utility: Check if any open position exists for this symbol        |
//+------------------------------------------------------------------+
bool HasAnyPositionOnSymbol(const string sym)
{
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) == sym)
      return true;
  }
  return false;
}

//+------------------------------------------------------------------+
//| Utility: Find our own (magic) position on this symbol             |
//+------------------------------------------------------------------+
bool GetOurPosition(const string sym, ulong &ticketOut, long &typeOut, double &priceOpenOut, double &slOut, double &tpOut, double &volumeOut)
{
  ticketOut = 0;
  typeOut = -1;
  slOut = 0; tpOut=0; volumeOut=0; priceOpenOut=0;
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) != sym) continue;
    if((ulong)PositionGetInteger(POSITION_MAGIC) != InpMagicNumber) continue;

    ticketOut     = (ulong)PositionGetInteger(POSITION_TICKET);
    typeOut       = (long)PositionGetInteger(POSITION_TYPE);
    priceOpenOut  = PositionGetDouble(POSITION_PRICE_OPEN);
    slOut         = PositionGetDouble(POSITION_SL);
    tpOut         = PositionGetDouble(POSITION_TP);
    volumeOut     = PositionGetDouble(POSITION_VOLUME);
    return true;
  }
  return false;
}

//+------------------------------------------------------------------+
//| Indicator handle creation                                         |
//+------------------------------------------------------------------+
bool CreateIndicators(const string sym)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);

  hFastEMA = iMA(sym, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(sym, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(sym, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(sym, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("Indicator handle creation failed. fast:",hFastEMA," slow:",hSlowEMA," rsi:",hRSI," atr:",hATR);
    return false;
  }
  return true;
}

//+------------------------------------------------------------------+
//| Read latest signal values at bar close                            |
//+------------------------------------------------------------------+
bool ReadSignals(const string sym, double &emaFastPrev, double &emaSlowPrev, double &emaFastCurr, double &emaSlowCurr, double &rsiCurr, double &atrCurr)
{
  double bufFast[3], bufSlow[3], bufRSI[3], bufATR[3];
  if(CopyBuffer(hFastEMA, 0, 0, 3, bufFast) < 3) return false;
  if(CopyBuffer(hSlowEMA, 0, 0, 3, bufSlow) < 3) return false;
  if(CopyBuffer(hRSI,     0, 0, 3, bufRSI)  < 2) return false;
  if(CopyBuffer(hATR,     0, 0, 3, bufATR)  < 1) return false;

  // Index 1 is the last closed bar, index 2 previous closed bar
  emaFastCurr = bufFast[1];
  emaSlowCurr = bufSlow[1];
  emaFastPrev = bufFast[2];
  emaSlowPrev = bufSlow[2];
  rsiCurr     = bufRSI[1];
  atrCurr     = bufATR[1];
  return true;
}

//+------------------------------------------------------------------+
//| Risk sizing using equity and ATR stop distance                    |
//+------------------------------------------------------------------+
double ComputePositionSize(const string sym, const bool isBuy, const double stopPrice)
{
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double riskAmount = equity * (InpRiskPerTradePct/100.0);
  if(riskAmount<=0) return 0.0;

  MqlTick tick; if(!SymbolInfoTick(sym,tick)) return 0.0;
  double entry = isBuy ? tick.ask : tick.bid;
  double stopDistance = MathAbs(entry - stopPrice);
  if(stopDistance <= 0) return 0.0;

  // Pip value approximation using tick value/size
  double tickValue = gTickValue;
  double tickSize  = gTickSize;
  if(tickValue<=0 || tickSize<=0) return 0.0;

  // Value per lot when price moves by stopDistance
  double points = stopDistance / gPoint;
  double moneyPerLot = (points * (tickValue / (tickSize / gPoint)));
  if(moneyPerLot<=0) return 0.0;

  double lots = riskAmount / moneyPerLot;
  return NormalizeVolume(lots);
}

//+------------------------------------------------------------------+
//| Margin guardrails and per-trade cap                               |
//+------------------------------------------------------------------+
bool ValidateMarginAndCap(const string sym, const ENUM_ORDER_TYPE type, double lots)
{
  if(lots<=0) return false;

  double price = 0.0;
  MqlTick tick; if(!SymbolInfoTick(sym,tick)) { Print("SymbolInfoTick failed"); return false; }
  if(type==ORDER_TYPE_BUY || type==ORDER_TYPE_BUY_LIMIT || type==ORDER_TYPE_BUY_STOP || type==ORDER_TYPE_BUY_STOP_LIMIT)
    price = tick.ask;
  else
    price = tick.bid;

  double margin = 0.0;
  if(!OrderCalcMargin(type, sym, lots, price, margin))
  {
    PrintFormat("OrderCalcMargin failed. type=%d lots=%.2f price=%.*f lastErr=%d", (int)type, lots, gDigits, price, GetLastError());
    return false;
  }

  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(freeMargin<=0)
  {
    Print("Free margin unavailable or <=0");
    return false;
  }

  if(margin > freeMargin)
  {
    PrintFormat("Insufficient free margin. Need=%.2f Free=%.2f", margin, freeMargin);
    return false;
  }

  double cap = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
  if(margin > cap)
  {
    PrintFormat("Per-trade margin cap exceeded. Margin=%.2f Cap=%.2f (%.2f%% of free)", margin, cap, InpMaxFreeMarginUsagePct);
    return false;
  }

  double marginLevel = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL);
  if(InpMinMarginLevelPct>0 && marginLevel>0 && marginLevel < InpMinMarginLevelPct)
  {
    PrintFormat("Margin level %.2f%% below threshold %.2f%%", marginLevel, InpMinMarginLevelPct);
    return false;
  }

  return true;
}

//+------------------------------------------------------------------+
//| Build SL/TP prices based on ATR and RR                            |
//+------------------------------------------------------------------+
void BuildSLTP(const bool isBuy, const double atr, const double rr, double &sl, double &tp)
{
  MqlTick tick; SymbolInfoTick(_Symbol, tick);
  double entry = isBuy ? tick.ask : tick.bid;
  double slDist = atr * InpATR_SL_Mult;
  double tpDist = slDist * rr;

  if(isBuy)
  {
    sl = NormalizePrice(entry - slDist);
    tp = NormalizePrice(entry + tpDist);
  }
  else
  {
    sl = NormalizePrice(entry + slDist);
    tp = NormalizePrice(entry - tpDist);
  }
}

//+------------------------------------------------------------------+
//| Spread and session filters                                        |
//+------------------------------------------------------------------+
bool PassesFilters()
{
  MqlTick tick; if(!SymbolInfoTick(_Symbol,tick)) return false;
  double spreadPoints = (tick.ask - tick.bid) / gPoint;
  if(spreadPoints > InpMaxSpreadPoints)
  {
    PrintFormat("Spread %.1f pts exceeds limit %d pts", spreadPoints, InpMaxSpreadPoints);
    return false;
  }
  datetime nowUTC = TimeGMT();
  int hour = TimeHour(nowUTC);
  if(hour>=0 && hour<24 && gSkipHour[hour])
  {
    PrintFormat("Trading skipped at UTC hour %d", hour);
    return false;
  }
  return true;
}

//+------------------------------------------------------------------+
//| Entry signal: EMA cross + RSI                                     |
//+------------------------------------------------------------------+
int EntrySignal(const double emaFastPrev, const double emaSlowPrev, const double emaFastCurr, const double emaSlowCurr, const double rsiCurr)
{
  bool goldenCross = (emaFastPrev <= emaSlowPrev) && (emaFastCurr > emaSlowCurr) && (rsiCurr >= InpRSI_Buy);
  bool deathCross  = (emaFastPrev >= emaSlowPrev) && (emaFastCurr < emaSlowCurr) && (rsiCurr <= InpRSI_Sell);
  if(goldenCross) return 1;  // buy
  if(deathCross)  return -1; // sell
  return 0;
}

//+------------------------------------------------------------------+
//| Trailing stop and breakeven management                            |
//+------------------------------------------------------------------+
void ManageTrailing()
{
  ulong ticket; long type; double open, sl, tp, vol;
  if(!GetOurPosition(_Symbol, ticket, type, open, sl, tp, vol)) return;

  MqlTick tick; if(!SymbolInfoTick(_Symbol,tick)) return;
  double price = (type==POSITION_TYPE_BUY)? tick.bid : tick.ask;

  // Compute ATR-based trail distance
  double atrBuf[2];
  if(CopyBuffer(hATR,0,0,2,atrBuf)<1) return;
  double atr = atrBuf[0];
  double trailDist = atr * InpATR_TrailMult;

  // Breakeven logic
  if(InpBreakevenRR > 0)
  {
    double slDist = atr * InpATR_SL_Mult;
    double bePriceBuy  = open + slDist * InpBreakevenRR;
    double bePriceSell = open - slDist * InpBreakevenRR;
    if(type==POSITION_TYPE_BUY && price >= bePriceBuy && (sl < open))
    {
      double newSL = NormalizePrice(open);
      trade.PositionModify(ticket, newSL, tp);
    }
    else if(type==POSITION_TYPE_SELL && price <= bePriceSell && (sl > open || sl==0))
    {
      double newSL = NormalizePrice(open);
      trade.PositionModify(ticket, newSL, tp);
    }
  }

  if(!InpAllowTrailing) return;

  if(type==POSITION_TYPE_BUY)
  {
    double desiredSL = NormalizePrice(price - trailDist);
    if(desiredSL > sl && (open < desiredSL)) // trail only forward and not before BE
    {
      if(gStopsLevelPoints>0)
      {
        double minSL = NormalizePrice(price - gStopsLevelPoints * gPoint);
        if(desiredSL < minSL) desiredSL = minSL;
      }
      trade.PositionModify(ticket, desiredSL, tp);
    }
  }
  else if(type==POSITION_TYPE_SELL)
  {
    double desiredSL = NormalizePrice(price + trailDist);
    if((sl==0 || desiredSL < sl) && (open > desiredSL))
    {
      if(gStopsLevelPoints>0)
      {
        double maxSL = NormalizePrice(price + gStopsLevelPoints * gPoint);
        if(desiredSL > maxSL) desiredSL = maxSL;
      }
      trade.PositionModify(ticket, desiredSL, tp);
    }
  }
}

//+------------------------------------------------------------------+
//| Order placement with strict one-position-per-symbol               |
//+------------------------------------------------------------------+
bool PlaceOrder(const int dir, const double sl, const double tp)
{
  if(dir==0) return false;
  if(HasAnyPositionOnSymbol(_Symbol))
  {
    Print("Entry blocked: existing position on symbol.");
    return false;
  }

  MqlTick tick; if(!SymbolInfoTick(_Symbol,tick)) return false;
  double price = (dir>0) ? tick.ask : tick.bid;

  // Compute initial size from SL distance
  double lots = ComputePositionSize(_Symbol, dir>0, sl);
  if(lots <= 0)
  {
    Print("Computed lot size <= 0; aborting entry.");
    return false;
  }

  // Validate margin and cap with computed lots; shrink if cap exceeded
  ENUM_ORDER_TYPE otype = (dir>0)? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  if(!ValidateMarginAndCap(_Symbol, otype, lots))
  {
    // Try to reduce lots proportionally to fit cap/free margin
    double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
    if(freeMargin<=0) return false;

    double margin=0.0;
    if(!OrderCalcMargin(otype, _Symbol, lots, price, margin)) return false;

    double cap = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
    if(margin<=0 || cap<=0) return false;

    double newLots = lots * (cap / margin) * 0.98; // 2% cushion
    newLots = NormalizeVolume(newLots);
    if(newLots<=0) { Print("Unable to size within margin cap."); return false; }

    if(!ValidateMarginAndCap(_Symbol, otype, newLots))
      return false;

    lots = newLots;
  }

  trade.SetExpertMagicNumber(InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool ok=false;
  if(dir>0)
    ok = trade.Buy(lots, _Symbol, price, sl, tp, "EMA/RSI Buy");
  else
    ok = trade.Sell(lots, _Symbol, price, sl, tp, "EMA/RSI Sell");

  if(!ok)
  {
    PrintFormat("Order send failed. ret=%s lastErr=%d", (string)ok, GetLastError());
    return false;
  }
  return true;
}

//+------------------------------------------------------------------+
//| OnInit                                                            |
//+------------------------------------------------------------------+
int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol))
  {
    Print("RefreshSymbolInfo failed");
    return INIT_FAILED;
  }

  if(!CreateIndicators(_Symbol))
  {
    Print("CreateIndicators failed");
    return INIT_FAILED;
  }

  ParseSkipHours(InpSkipHoursUTC);
  gLastClosedBarTime = 0;

  return INIT_SUCCEEDED;
}

//+------------------------------------------------------------------+
//| OnDeinit                                                          |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

//+------------------------------------------------------------------+
//| OnTick                                                            |
//+------------------------------------------------------------------+
void OnTick()
{
  static datetime lastBarTime = 0;

  // Filters first
  if(!PassesFilters())
    return;

  // Ensure symbol info up to date occasionally
  static int tickCount=0; if(++tickCount%1000==0) RefreshSymbolInfo(_Symbol);

  // Work only on bar close for signals
  datetime times[3];
  if(CopyTime(_Symbol, InpTimeframe, 0, 3, times) < 2) return;
  datetime lastClosed = times[1];
  if(lastClosed == gLastClosedBarTime)
  {
    // Manage trailing on every tick
    ManageTrailing();
    return;
  }

  gLastClosedBarTime = lastClosed;

  double emaFastPrev, emaSlowPrev, emaFastCurr, emaSlowCurr, rsiCurr, atrCurr;
  if(!ReadSignals(_Symbol, emaFastPrev, emaSlowPrev, emaFastCurr, emaSlowCurr, rsiCurr, atrCurr))
    return;

  if(InpATR_MinFilter>0 && atrCurr < InpATR_MinFilter)
  {
    PrintFormat("ATR %.5f below minimum filter %.5f", atrCurr, InpATR_MinFilter);
    return;
  }

  int sig = EntrySignal(emaFastPrev, emaSlowPrev, emaFastCurr, emaSlowCurr, rsiCurr);
  if(sig==0)
  {
    ManageTrailing();
    return;
  }

  // Build SL/TP
  double sl=0.0, tp=0.0;
  BuildSLTP(sig>0, atrCurr, InpRR, sl, tp);

  // Respect stops/freeze levels
  if(gStopsLevelPoints>0)
  {
    MqlTick tick; SymbolInfoTick(_Symbol,tick);
    if(sig>0)
    {
      double minSL = NormalizePrice(tick.bid - gStopsLevelPoints * gPoint);
      if(sl < minSL) sl = minSL;
    }
    else
    {
      double maxSL = NormalizePrice(tick.ask + gStopsLevelPoints * gPoint);
      if(sl > maxSL) sl = maxSL;
    }
  }

  // Place order with full margin/risk validation
  PlaceOrder(sig, sl, tp);

  // Manage trailing after entry attempt
  ManageTrailing();
}

//+------------------------------------------------------------------+
//|                                         EMA_RSI_ATR_Manager.mq5  |
//|  EMA Cross + RSI + ATR with robust risk & margin controls        |
//|  One-position-per-symbol, spread/session filters, trailing stop  |
//+------------------------------------------------------------------+
#property strict
#property version   "1.30"
#property description "EMA Cross + RSI + ATR strategy with full trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct           = 0.5;   // Percent of equity risk per trade (e.g., 0.5 = 0.5%)
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Do not open if margin level would fall below this (%); ignored if <=0
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastSignalBarTime = 0;

// Symbol parameters cache
string  gSymbol;
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC) map
bool    gSkipHour[24];

//------------------------------------------------------------------
// Helpers
//------------------------------------------------------------------
void LogLastError(const string context)
{
  int ec = GetLastError();
  PrintFormat("%s | Error %d: %s", context, ec, ErrorDescription(ec));
  ResetLastError();
}

void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

bool RefreshSymbolInfo(const string sym)
{
  gSymbol = sym;
  if(!SymbolSelect(gSymbol, true))
  {
    LogLastError("SymbolSelect failed");
    return false;
  }

  gPoint  = SymbolInfoDouble(gSymbol, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(gSymbol, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE);
  gTickValue= SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MIN);
  gMaxVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MAX);
  gVolStep  = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints  = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_FREEZE_LEVEL);

  long trade_mode = SymbolInfoInteger(gSymbol, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED || trade_mode == SYMBOL_TRADE_MODE_CLOSEONLY)
  {
    PrintFormat("Trading not allowed for symbol %s (mode=%d)", gSymbol, trade_mode);
    return false;
  }
  return true;
}

bool SessionFilterUTC()
{
  datetime now = TimeCurrent();
  MqlDateTime dt; TimeToStruct(now, dt);
  int h = dt.hour; // server time; assume server ~ UTC or user provides UTC-aligned hours
  if(h>=0 && h<24 && gSkipHour[h]) return false;
  return true;
}

bool SpreadOK()
{
  double spread_points = (SymbolInfoDouble(gSymbol, SYMBOL_ASK) - SymbolInfoDouble(gSymbol, SYMBOL_BID))/gPoint;
  return (spread_points <= InpMaxSpreadPoints);
}

int PositionsOnSymbol()
{
  int count=0;
  for(int i=0;i<PositionsTotal();++i)
  {
    string s; ulong magic; long type;
    if(!PositionGet(i)) continue;
    s = PositionGetString(POSITION_SYMBOL);
    magic = (ulong)PositionGetInteger(POSITION_MAGIC);
    type  = (long)PositionGetInteger(POSITION_TYPE);
    if(s==gSymbol && magic==InpMagicNumber && (type==POSITION_TYPE_BUY || type==POSITION_TYPE_SELL))
      count++;
  }
  return count;
}

// Normalize volume to broker constraints
double NormalizeVolume(double lots)
{
  if(lots < gMinVolume) lots = gMinVolume;
  if(lots > gMaxVolume) lots = gMaxVolume;
  double steps = MathFloor((lots - gMinVolume + 1e-12)/gVolStep);
  double norm  = gMinVolume + steps*gVolStep;
  return MathMax(gMinVolume, MathMin(gMaxVolume, norm));
}

// Calculate lot size from equity risk (%) and stop distance using OrderCalcMargin
bool CalcPositionSize(bool is_buy, double entry_price, double stop_price, double &out_lots, string &reason)
{
  out_lots = 0.0;
  reason = "";

  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(equity<=0.0 || free_margin<=0.0)
  {
    reason = "Invalid equity or free margin";
    return false;
  }

  double risk_amount = equity * (InpRiskPerTradePct/100.0);
  if(risk_amount <= 0.0)
  {
    reason = "Risk amount <= 0";
    return false;
  }

  double stop_dist = MathAbs(entry_price - stop_price);
  if(stop_dist <= 0.0)
  {
    reason = "Stop distance <= 0";
    return false;
  }

  // Value per point approximation using tick value/size
  double points_in_stop = stop_dist / gPoint;
  if(points_in_stop <= 0.0)
  {
    reason = "Computed stop points <= 0";
    return false;
  }

  // Cost per lot for that stop (approx) using tick value mapping
  double value_per_point_per_lot = (gTickValue / gTickSize) * gPoint; // convert to per-point per lot
  if(value_per_point_per_lot <= 0.0)
  {
    reason = "Invalid tick mapping";
    return false;
  }

  double est_loss_per_lot = points_in_stop * value_per_point_per_lot;
  if(est_loss_per_lot <= 0.0)
  {
    reason = "Estimated loss per lot <= 0";
    return false;
  }

  double lots_by_risk = risk_amount / est_loss_per_lot;
  if(lots_by_risk <= 0.0)
  {
    reason = "Lots by risk <= 0";
    return false;
  }

  // Now ensure margin feasibility and per-trade margin cap using OrderCalcMargin
  double test_lots = NormalizeVolume(lots_by_risk);
  if(test_lots < gMinVolume)
  {
    reason = "Computed lots below min volume";
    return false;
  }

  // Cap by free margin usage percentage
  double allowed_margin_cap = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  double margin_needed = 0.0;
  if(!OrderCalcMargin(is_buy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, gSymbol, test_lots, entry_price, margin_needed))
  {
    LogLastError("OrderCalcMargin failed");
    reason = "OrderCalcMargin failed";
    return false;
  }

  if(margin_needed <= 0.0)
  {
    reason = "Non-positive margin needed";
    return false;
  }

  if(margin_needed > allowed_margin_cap)
  {
    // Scale lots down to fit cap (linear approx)
    double scale = allowed_margin_cap / margin_needed;
    test_lots = NormalizeVolume(test_lots * scale);

    if(!OrderCalcMargin(is_buy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, gSymbol, test_lots, entry_price, margin_needed))
    {
      LogLastError("OrderCalcMargin recheck failed");
      reason = "OrderCalcMargin recheck failed";
      return false;
    }

    if(margin_needed > allowed_margin_cap)
    {
      reason = "Margin cap binding; lots too small after scaling";
      return false;
    }
  }

  // Predict margin level after opening: (equity / margin_used_total)*100
  double margin_current = AccountInfoDouble(ACCOUNT_MARGIN);
  double margin_level_current = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL); // may be 0 or NAN on some brokers

  double predicted_margin_total = margin_current + margin_needed;
  double predicted_margin_level = (predicted_margin_total>0.0) ? (equity / predicted_margin_total) * 100.0 : 0.0;

  if(InpMinMarginLevelPct > 0.0 && predicted_margin_level < InpMinMarginLevelPct)
  {
    reason = StringFormat("Predicted margin level %.1f%% below threshold %.1f%%", predicted_margin_level, InpMinMarginLevelPct);
    return false;
  }

  // Also ensure we still have some free margin left afterwards
  if(free_margin - margin_needed <= 0.0)
  {
    reason = "Insufficient free margin after reserve";
    return false;
  }

  out_lots = test_lots;
  return true;
}

bool CreateIndicators()
{
  // Release old if needed
  if(hFastEMA!=INVALID_HANDLE) { IndicatorRelease(hFastEMA); hFastEMA=INVALID_HANDLE; }
  if(hSlowEMA!=INVALID_HANDLE) { IndicatorRelease(hSlowEMA); hSlowEMA=INVALID_HANDLE; }
  if(hRSI!=INVALID_HANDLE)     { IndicatorRelease(hRSI);     hRSI=INVALID_HANDLE; }
  if(hATR!=INVALID_HANDLE)     { IndicatorRelease(hATR);     hATR=INVALID_HANDLE; }

  hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  if(hFastEMA==INVALID_HANDLE) { LogLastError("iMA fast failed"); return false; }

  hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  if(hSlowEMA==INVALID_HANDLE) { LogLastError("iMA slow failed"); return false; }

  hRSI = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  if(hRSI==INVALID_HANDLE)     { LogLastError("iRSI failed"); return false; }

  hATR = iATR(gSymbol, InpTimeframe, InpATRPeriod);
  if(hATR==INVALID_HANDLE)     { LogLastError("iATR failed"); return false; }

  return true;
}

bool CopyLatest(const int handle, const int count, double &out[])
{
  ArraySetAsSeries(out, true);
  int copied = CopyBuffer(handle, 0, 0, count, out);
  if(copied < count)
  {
    LogLastError("CopyBuffer insufficient data");
    return false;
  }
  return true;
}

bool GetSignals(double &emaFast0, double &emaFast1, double &emaSlow0, double &emaSlow1, double &rsi0, double &atr0)
{
  double bFast[3], bSlow[3], bRSI[2], bATR[2];
  if(!CopyLatest(hFastEMA, 3, bFast)) return false;
  if(!CopyLatest(hSlowEMA, 3, bSlow)) return false;
  if(!CopyLatest(hRSI,   2, bRSI))    return false;
  if(!CopyLatest(hATR,   2, bATR))    return false;

  emaFast0 = bFast[0]; emaFast1 = bFast[1];
  emaSlow0 = bSlow[0]; emaSlow1 = bSlow[1];
  rsi0     = bRSI[0];
  atr0     = bATR[0];
  return !(MathIsValidNumber(emaFast0)==false || MathIsValidNumber(emaSlow0)==false || MathIsValidNumber(rsi0)==false || MathIsValidNumber(atr0)==false);
}

bool NewBarOccurred()
{
  static datetime last_time=0;
  MqlRates rates[];
  ArraySetAsSeries(rates,true);
  if(CopyRates(gSymbol, InpTimeframe, 0, 2, rates) < 2) return false;
  datetime t = rates[0].time;
  if(t != last_time)
  {
    last_time = t;
    return true;
  }
  return false;
}

void TrailAndBreakeven()
{
  if(!InpAllowTrailing) return;

  for(int i=0;i<PositionsTotal();++i)
  {
    if(!PositionGet(i)) continue;
    string sym = PositionGetString(POSITION_SYMBOL);
    if(sym != gSymbol) continue;
    ulong mg  = (ulong)PositionGetInteger(POSITION_MAGIC);
    if(mg != InpMagicNumber) continue;

    long   type   = (long)PositionGetInteger(POSITION_TYPE);
    double price  = PositionGetDouble(POSITION_PRICE_OPEN);
    double sl     = PositionGetDouble(POSITION_SL);
    double tp     = PositionGetDouble(POSITION_TP);
    double vol    = PositionGetDouble(POSITION_VOLUME);

    double bid = SymbolInfoDouble(gSymbol, SYMBOL_BID);
    double ask = SymbolInfoDouble(gSymbol, SYMBOL_ASK);

    // ATR-based trailing distance
    double atr_buf[2];
    if(!CopyLatest(hATR, 2, atr_buf)) continue;
    double trail_dist = MathMax(atr_buf[0]*InpATR_TrailMult, gStopsLevelPoints*gPoint);

    // Breakeven move
    if(InpBreakevenRR > 0.0 && tp>0 && sl>0)
    {
      double initial_risk = MathAbs(price - sl);
      double be_trigger   = initial_risk * InpBreakevenRR;
      if(type==POSITION_TYPE_BUY)
      {
        if((bid - price) >= be_trigger)
        {
          double new_sl = MathMax(sl, price + (gPoint*1));
          if(new_sl < (bid - trail_dist)) new_sl = bid - trail_dist; // don't reduce trailing opportunity
          if(new_sl > sl + gPoint && new_sl < bid - gStopsLevelPoints*gPoint)
          {
            trade.SetDeviationInPoints(InpSlippagePoints);
            if(!trade.PositionModify(gSymbol, new_sl, tp)) LogLastError("PositionModify BE BUY failed");
          }
        }
      }
      else if(type==POSITION_TYPE_SELL)
      {
        if((price - ask) >= be_trigger)
        {
          double new_sl = MathMin(sl, price - (gPoint*1));
          if(new_sl > (ask + trail_dist)) new_sl = ask + trail_dist;
          if(new_sl < sl - gPoint && new_sl > ask + gStopsLevelPoints*gPoint)
          {
            trade.SetDeviationInPoints(InpSlippagePoints);
            if(!trade.PositionModify(gSymbol, new_sl, tp)) LogLastError("PositionModify BE SELL failed");
          }
        }
      }
    }

    // Classic trailing by ATR
    if(type==POSITION_TYPE_BUY)
    {
      double new_sl = bid - trail_dist;
      if(sl < new_sl - gPoint && new_sl < bid - gStopsLevelPoints*gPoint)
      {
        trade.SetDeviationInPoints(InpSlippagePoints);
        if(!trade.PositionModify(gSymbol, new_sl, tp)) LogLastError("PositionModify trail BUY failed");
      }
    }
    else if(type==POSITION_TYPE_SELL)
    {
      double new_sl = ask + trail_dist;
      if(sl > new_sl + gPoint && new_sl > ask + gStopsLevelPoints*gPoint)
      {
        trade.SetDeviationInPoints(InpSlippagePoints);
        if(!trade.PositionModify(gSymbol, new_sl, tp)) LogLastError("PositionModify trail SELL failed");
      }
    }
  }
}

bool OpenPosition(bool is_buy, double entry_price, double sl, double tp)
{
  double lots; string why;
  if(!CalcPositionSize(is_buy, entry_price, sl, lots, why))
  {
    PrintFormat("Position sizing failed: %s", why);
    return false;
  }

  MqlTradeRequest req; MqlTradeResult res; ZeroMemory(req); ZeroMemory(res);
  req.action   = TRADE_ACTION_DEAL;
  req.symbol   = gSymbol;
  req.magic    = InpMagicNumber;
  req.type     = is_buy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  req.price    = is_buy ? SymbolInfoDouble(gSymbol, SYMBOL_ASK) : SymbolInfoDouble(gSymbol, SYMBOL_BID);
  req.sl       = sl;
  req.tp       = tp;
  req.volume   = lots;
  req.deviation= InpSlippagePoints;
  req.type_filling = ORDER_FILLING_FOK;
  req.type_time    = ORDER_TIME_GTC;

  if(gFreezeLevelPoints>0)
  {
    // Ensure SL/TP not within freeze level; if so, send without and modify after
    double mdist = gFreezeLevelPoints * gPoint;
    bool near_freeze = false;
    if(is_buy)
    {
      if(sl>0 && (req.price - sl) < mdist) near_freeze = true;
      if(tp>0 && (tp - req.price) < mdist) near_freeze = true;
    }
    else
    {
      if(sl>0 && (sl - req.price) < mdist) near_freeze = true;
      if(tp>0 && (req.price - tp) < mdist) near_freeze = true;
    }
    if(near_freeze) { req.sl=0.0; req.tp=0.0; }
  }

  trade.SetDeviationInPoints(InpSlippagePoints);
  if(!OrderSend(req, res))
  {
    LogLastError("OrderSend failed");
    return false;
  }

  if(res.retcode != TRADE_RETCODE_DONE && res.retcode != TRADE_RETCODE_PLACED)
  {
    PrintFormat("Order rejected retcode=%d comment=%s", res.retcode, res.comment);
    return false;
  }

  // If SL/TP were stripped due to freeze, modify now
  if((req.sl==0.0 || req.tp==0.0) && (sl>0.0 || tp>0.0))
  {
    // Get position and modify
    if(PositionSelect(gSymbol))
    {
      double cur_tp = PositionGetDouble(POSITION_TP);
      double cur_sl = PositionGetDouble(POSITION_SL);
      double new_sl = (req.sl==0.0) ? sl : cur_sl;
      double new_tp = (req.tp==0.0) ? tp : cur_tp;
      if(!trade.PositionModify(gSymbol, new_sl, new_tp))
        LogLastError("PositionModify post-freeze failed");
    }
  }

  return true;
}

int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol))
  {
    Print("Symbol info refresh failed; EA disabled");
    return(INIT_FAILED);
  }

  ParseSkipHours(InpSkipHoursUTC);

  if(!CreateIndicators())
  {
    Print("Indicator creation failed; EA disabled");
    return(INIT_FAILED);
  }

  gLastSignalBarTime = 0;
  return(INIT_SUCCEEDED);
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
  if(!RefreshSymbolInfo(_Symbol)) return;

  if(!SessionFilterUTC()) return;
  if(!SpreadOK()) return;

  // One-position-per-symbol (by magic)
  if(PositionsOnSymbol() > 0)
  {
    TrailAndBreakeven();
    return;
  }

  // Work only on new bars for stability
  if(!NewBarOccurred()) return;

  double emaFast0, emaFast1, emaSlow0, emaSlow1, rsi0, atr0;
  if(!GetSignals(emaFast0, emaFast1, emaSlow0, emaSlow1, rsi0, atr0)) return;

  if(InpATR_MinFilter > 0.0 && atr0 < InpATR_MinFilter) return;

  double bid = SymbolInfoDouble(gSymbol, SYMBOL_BID);
  double ask = SymbolInfoDouble(gSymbol, SYMBOL_ASK);

  // Determine signals: EMA cross confirmation with RSI filter (use previous bar cross)
  bool bull_cross = (emaFast1 < emaSlow1) && (emaFast0 > emaSlow0) && (rsi0 >= InpRSI_Buy);
  bool bear_cross = (emaFast1 > emaSlow1) && (emaFast0 < emaSlow0) && (rsi0 <= InpRSI_Sell);

  // Compute SL/TP based on ATR
  double sl_buy = 0.0, tp_buy = 0.0, sl_sell = 0.0, tp_sell = 0.0;
  double sl_dist = MathMax(atr0*InpATR_SL_Mult, gStopsLevelPoints*gPoint);
  if(sl_dist <= 0.0) return;

  sl_buy  = ask - sl_dist;
  sl_sell = bid + sl_dist;

  double rr = MathMax(1.0, InpRR);
  tp_buy  = ask + sl_dist*rr;
  tp_sell = bid - sl_dist*rr;

  // Sanity against freeze levels
  double fz = gFreezeLevelPoints * gPoint;
  if(fz > 0)
  {
    if((ask - sl_buy) < fz) sl_buy = ask - (fz + gPoint);
    if((sl_sell - bid) < fz) sl_sell = bid + (fz + gPoint);
    if((tp_buy - ask) < fz)  tp_buy = ask + (fz + gPoint);
    if((bid - tp_sell) < fz) tp_sell = bid - (fz + gPoint);
  }

  // Open trades with margin/risk checks
  if(bull_cross)
  {
    OpenPosition(true, ask, sl_buy, tp_buy);
  }
  else if(bear_cross)
  {
    OpenPosition(false, bid, sl_sell, tp_sell);
  }

  // Manage trailing for any newly opened position
  TrailAndBreakeven();
}

