#property strict
#property version   "1.50"
#property description "EMA Cross + RSI + ATR strategy with full trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct           = 0.5;   // Percent of equity risk per trade (0.5 = 0.5%)
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Block if projected margin level < this (%); ignored if <=0
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastSignalBarTime = 0;

// Symbol parameters cache
string  gSymbol;
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints  = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC) map
bool    gSkipHour[24];

//==================================================================
// Helpers
//==================================================================
void LogLastError(const string context)
{
  int err = GetLastError();
  PrintFormat("%s | Error %d: %s", context, err, ErrorDescription(err));
  ResetLastError();
}

void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

bool RefreshSymbolInfo(const string sym)
{
  gSymbol = sym;
  if(!SymbolSelect(gSymbol, true))
  {
    LogLastError("SymbolSelect failed");
    return false;
  }

  gPoint   = SymbolInfoDouble(gSymbol, SYMBOL_POINT);
  gDigits  = (int)SymbolInfoInteger(gSymbol, SYMBOL_DIGITS);
  gTickSize= SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE);
  gTickValue=SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume=SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MIN);
  gMaxVolume=SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MAX);
  gVolStep  =SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints  = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_FREEZE_LEVEL);

  long trade_mode = SymbolInfoInteger(gSymbol, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED || trade_mode == SYMBOL_TRADE_MODE_CLOSEONLY)
  {
    PrintFormat("Trading not allowed for symbol %s (mode=%d)", gSymbol, trade_mode);
    return false;
  }

  return (gPoint>0.0 && gMinVolume>0.0 && gVolStep>0.0);
}

bool GetBidAsk(double &bid, double &ask)
{
  MqlTick tick;
  if(!SymbolInfoTick(gSymbol, tick))
  {
    LogLastError("SymbolInfoTick failed");
    return false;
  }
  bid = tick.bid;
  ask = tick.ask;
  return (bid>0.0 && ask>0.0 && ask>bid);
}

int OpenPositionsForSymbol()
{
  int count=0;
  for(int i=0;i<PositionsTotal();i++)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(!PositionSelectByTicket(ticket)) continue;
    if(PositionGetString(POSITION_SYMBOL)==gSymbol && PositionGetInteger(POSITION_MAGIC)==(long)InpMagicNumber)
      count++;
  }
  return count;
}

bool InSkipHour()
{
  datetime now_utc = TimeGMT();
  MqlDateTime t;
  TimeToStruct(now_utc, t);
  int hour = t.hour;
  if(hour<0 || hour>23) return false;
  return gSkipHour[hour];
}

bool CheckSpreadOK()
{
  double bid,ask;
  if(!GetBidAsk(bid,ask)) return false;
  double spread_points = (ask - bid)/gPoint;
  if(spread_points > InpMaxSpreadPoints)
  {
    PrintFormat("Spread too high: %.1f > %d points", spread_points, InpMaxSpreadPoints);
    return false;
  }
  return true;
}

// Indicator value fetchers (shift 1 = last closed bar)
double GetEMA(int handle,int shift)
{
  double buf[]; ArraySetAsSeries(buf,true);
  if(CopyBuffer(handle,0,shift,1,buf)!=1) { LogLastError("CopyBuffer EMA failed"); return 0.0; }
  return buf[0];
}

double GetRSI(int handle,int shift)
{
  double buf[]; ArraySetAsSeries(buf,true);
  if(CopyBuffer(handle,0,shift,1,buf)!=1) { LogLastError("CopyBuffer RSI failed"); return 50.0; }
  return buf[0];
}

double GetATR(int handle,int shift)
{
  double buf[]; ArraySetAsSeries(buf,true);
  if(CopyBuffer(handle,0,shift,1,buf)!=1) { LogLastError("CopyBuffer ATR failed"); return 0.0; }
  return buf[0];
}

// Normalize volume to broker constraints
double NormalizeVolume(double lots)
{
  if(lots<gMinVolume) lots = gMinVolume;
  if(lots>gMaxVolume) lots = gMaxVolume;
  double steps = MathFloor((lots - gMinVolume + 1e-12)/gVolStep + 0.5);
  double norm  = gMinVolume + steps*gVolStep;
  // guard against rounding beyond bounds
  if(norm<gMinVolume) norm=gMinVolume;
  if(norm>gMaxVolume) norm=gMaxVolume;
  return norm;
}

// Calculate position size (lots) using equity risk and OrderCalcMargin constraints
bool CalcLotsByEquityRisk(bool is_buy, double entry_price, double sl_price, double &lots, double &proj_margin, double &proj_margin_level)
{
  lots = 0.0; proj_margin = 0.0; proj_margin_level = 0.0;

  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double balance= AccountInfoDouble(ACCOUNT_BALANCE);
  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double margin      = AccountInfoDouble(ACCOUNT_MARGIN);

  if(equity<=0.0 || free_margin<=0.0) { Print("Equity or free margin non-positive"); return false; }

  // Risk per trade in account currency using SL distance
  double sl_dist = MathAbs(entry_price - sl_price);
  if(sl_dist <= 0.0)
  {
    Print("SL distance invalid");
    return false;
  }

  // Tick value per lot to convert price move to currency
  if(gTickValue<=0.0 || gTickSize<=0.0) { Print("Tick specs invalid"); return false; }

  double risk_amount = equity * (InpRiskPerTradePct/100.0);
  if(risk_amount <= 0.0) { Print("Risk amount <= 0"); return false; }

  // Currency loss per lot at SL distance
  double ticks_at_sl = sl_dist / gTickSize;
  double loss_per_lot = ticks_at_sl * gTickValue;
  if(loss_per_lot<=0.0) { Print("Computed loss_per_lot <= 0"); return false; }

  double raw_lots = risk_amount / loss_per_lot;
  if(raw_lots <= 0.0) { Print("Raw lots <= 0"); return false; }

  // Respect per-trade margin cap based on free margin
  double max_margin_for_trade = free_margin * (InpMaxFreeMarginUsagePct/100.0);

  // Find lots limited by margin cap using OrderCalcMargin
  double step_lots = NormalizeVolume(raw_lots);
  // If margin too high, reduce stepwise
  for(int i=0;i<1000;i++)
  {
    double m=0.0;
    if(!OrderCalcMargin(is_buy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, gSymbol, step_lots, entry_price, m))
    { LogLastError("OrderCalcMargin failed"); return false; }
    if(m<=max_margin_for_trade && m<free_margin)
    {
      proj_margin = m;
      break;
    }
    step_lots -= gVolStep;
    if(step_lots < gMinVolume - 1e-12)
    {
      Print("No feasible lot size within margin cap");
      return false;
    }
    step_lots = NormalizeVolume(step_lots);
  }

  // Projected margin level after opening = (Equity / (Margin + new_margin)) * 100
  double new_total_margin = margin + proj_margin;
  if(new_total_margin<=0.0) { Print("Projected total margin <= 0"); return false; }
  proj_margin_level = (equity / new_total_margin) * 100.0;
  if(InpMinMarginLevelPct>0.0 && proj_margin_level < InpMinMarginLevelPct)
  {
    PrintFormat("Projected margin level %.1f%% < min %.1f%%", proj_margin_level, InpMinMarginLevelPct);
    return false;
  }

  lots = step_lots;
  return (lots>=gMinVolume && lots<=gMaxVolume);
}

void PlaceOrder(bool is_buy, double entry_price, double sl_price, double tp_price)
{
  double lots, proj_margin, proj_ml;
  if(!CalcLotsByEquityRisk(is_buy, entry_price, sl_price, lots, proj_margin, proj_ml))
  {
    Print("Sizing failed; order not sent");
    return;
  }

  trade.SetExpertMagicNumber((int)InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool ok=false;
  if(is_buy)
    ok = trade.Buy(lots, gSymbol, entry_price, sl_price, tp_price, "EMA/RSI Buy");
  else
    ok = trade.Sell(lots, gSymbol, entry_price, sl_price, tp_price, "EMA/RSI Sell");

  if(!ok)
  {
    LogLastError("Order send failed");
  }
  else
  {
    PrintFormat("Order placed: %s lots=%.2f SL=%.5f TP=%.5f proj_margin=%.2f proj_ML=%.1f%%",
                is_buy?"BUY":"SELL", lots, sl_price, tp_price, proj_margin, proj_ml);
  }
}

void ManageTrailing()
{
  if(!InpAllowTrailing) return;
  if(PositionsTotal()==0) return;

  double atr = GetATR(hATR,1);
  if(atr<=0.0) return;
  double trail = atr * InpATR_TrailMult;
  if(trail<=0.0) return;

  for(int i=0;i<PositionsTotal();i++)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(!PositionSelectByTicket(ticket)) continue;
    if(PositionGetString(POSITION_SYMBOL)!=gSymbol) continue;
    if(PositionGetInteger(POSITION_MAGIC)!=(long)InpMagicNumber) continue;

    long   type   = PositionGetInteger(POSITION_TYPE);
    double price  = PositionGetDouble(POSITION_PRICE_OPEN);
    double sl     = PositionGetDouble(POSITION_SL);
    double tp     = PositionGetDouble(POSITION_TP);
    double volume = PositionGetDouble(POSITION_VOLUME);

    double bid,ask; if(!GetBidAsk(bid,ask)) return;

    // Breakeven logic
    if(InpBreakevenRR>0.0)
    {
      double risk = MathAbs(price - sl);
      if(risk>0.0)
      {
        double rr_price = (type==POSITION_TYPE_BUY)? price + InpBreakevenRR*risk : price - InpBreakevenRR*risk;
        bool reached = (type==POSITION_TYPE_BUY)? (bid>=rr_price) : (ask<=rr_price);
        double be_sl = (type==POSITION_TYPE_BUY)? price + (gStopsLevelPoints+2)*gPoint : price - (gStopsLevelPoints+2)*gPoint; // tiny offset
        if(reached)
        {
          if((type==POSITION_TYPE_BUY && (sl<price || sl==0.0)) || (type==POSITION_TYPE_SELL && (sl>price || sl==0.0)))
          {
            if(!trade.PositionModify(gSymbol, be_sl, tp)) LogLastError("Set BE SL failed");
          }
        }
      }
    }

    // ATR trailing
    if(type==POSITION_TYPE_BUY)
    {
      double new_sl = (bid - trail);
      // respect stops level and only tighten SL
      double min_sl = price - (gStopsLevelPoints+2)*gPoint;
      if(new_sl<min_sl) new_sl=min_sl;
      if(sl==0.0 || new_sl>sl + gPoint)
      {
        if(!trade.PositionModify(gSymbol, NormalizeDouble(new_sl, gDigits), tp)) LogLastError("Trail SL (BUY) failed");
      }
    }
    else if(type==POSITION_TYPE_SELL)
    {
      double new_sl = (ask + trail);
      double max_sl = price + (gStopsLevelPoints+2)*gPoint;
      if(new_sl>max_sl) new_sl=max_sl;
      if(sl==0.0 || new_sl<sl - gPoint)
      {
        if(!trade.PositionModify(gSymbol, NormalizeDouble(new_sl, gDigits), tp)) LogLastError("Trail SL (SELL) failed");
      }
    }
  }
}

bool BuildSignals(bool &buy, bool &sell, double &entry, double &sl, double &tp)
{
  buy=false; sell=false; entry=0.0; sl=0.0; tp=0.0;

  // Ensure we work on closed bar only
  MqlRates rates[]; ArraySetAsSeries(rates,true);
  if(CopyRates(gSymbol, InpTimeframe, 0, 3, rates)<3) { LogLastError("CopyRates failed"); return false; }
  datetime last_bar_time = rates[1].time; // last closed bar
  if(last_bar_time==gLastSignalBarTime) return false; // already evaluated

  double ema_fast_1 = GetEMA(hFastEMA,1);
  double ema_slow_1 = GetEMA(hSlowEMA,1);
  double ema_fast_2 = GetEMA(hFastEMA,2);
  double ema_slow_2 = GetEMA(hSlowEMA,2);
  double rsi_1      = GetRSI(hRSI,1);
  double atr_1      = GetATR(hATR,1);

  if(ema_fast_1==0.0 || ema_slow_1==0.0 || ema_fast_2==0.0 || ema_slow_2==0.0) return false;
  if(InpATR_MinFilter>0.0 && atr_1 < InpATR_MinFilter) return false;

  // Cross detection on closed bar
  bool bull_cross = (ema_fast_2<=ema_slow_2) && (ema_fast_1>ema_slow_1) && (rsi_1>=InpRSI_Buy);
  bool bear_cross = (ema_fast_2>=ema_slow_2) && (ema_fast_1<ema_slow_1) && (rsi_1<=InpRSI_Sell);

  double bid,ask; if(!GetBidAsk(bid,ask)) return false;

  if(bull_cross)
  {
    entry = ask;
    sl    = entry - InpATR_SL_Mult*atr_1;
    double tp_dist = (entry - sl) * InpRR;
    tp    = entry + tp_dist;
    buy   = true;
  }
  else if(bear_cross)
  {
    entry = bid;
    sl    = entry + InpATR_SL_Mult*atr_1;
    double tp_dist = (sl - entry) * InpRR;
    tp    = entry - tp_dist;
    sell  = true;
  }

  if(buy||sell)
  {
    // Respect stop levels
    if(gStopsLevelPoints>0)
    {
      if(buy)
      {
        if((entry - sl) < (gStopsLevelPoints+2)*gPoint) sl = entry - (gStopsLevelPoints+2)*gPoint;
      }
      else
      {
        if((sl - entry) < (gStopsLevelPoints+2)*gPoint) sl = entry + (gStopsLevelPoints+2)*gPoint;
      }
    }
    gLastSignalBarTime = last_bar_time;
    return true;
  }

  return false;
}

//==================================================================
// MT5 Standard Handlers
//==================================================================
int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol))
  {
    Print("Symbol info refresh failed");
    return INIT_FAILED;
  }

  ParseSkipHours(InpSkipHoursUTC);

  // Create indicators
  hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(gSymbol, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("Indicator handle creation failed");
    return INIT_FAILED;
  }

  return INIT_SUCCEEDED;
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI    !=INVALID_HANDLE) IndicatorRelease(hRSI);
  if(hATR    !=INVALID_HANDLE) IndicatorRelease(hATR);
}

void OnTick()
{
  // Filters
  if(InSkipHour()) return;
  if(!CheckSpreadOK()) return;

  // One-position-per-symbol rule
  if(OpenPositionsForSymbol()>0)
  {
    ManageTrailing();
    return;
  }

  bool buy=false, sell=false; double entry=0.0, sl=0.0, tp=0.0;
  if(!BuildSignals(buy,sell,entry,sl,tp)) return;

  // Final price sanity
  if(entry<=0.0 || sl<=0.0 || tp<=0.0) return;
  if(!RefreshSymbolInfo(_Symbol)) return;

  // Place order with full sizing and margin checks
  PlaceOrder(buy, entry, sl, tp);
}

//+------------------------------------------------------------------+
//|                                                     EMA_RSI_EA.mq5 |
//| Complete MT5 Expert Advisor with EMA/RSI entries, SL/TP, trailing |
//| spread/session filters, one-position-per-symbol, and robust margin |
//| sizing using OrderCalcMargin with free-margin/level checks and cap |
//| Includes explicit error handling end-to-end                        |
//+------------------------------------------------------------------+
#property copyright   ""
#property version     "1.00"
#property strict
#property description "EMA/RSI strategy with margin-aware position sizing and risk controls"

#include <Trade/Trade.mqh>

CTrade trade;

//--- Inputs
input string   InpSymbol               = _Symbol;         // Trading symbol
input ENUM_TIMEFRAMES InpTF            = PERIOD_M5;       // Working timeframe

// Strategy inputs
input int      InpFastEMA              = 12;              // Fast EMA period
input int      InpSlowEMA              = 26;              // Slow EMA period
input int      InpRSIPeriod            = 14;              // RSI period
input double   InpRSIOverbought        = 70.0;            // RSI overbought level
input double   InpRSIOversold          = 30.0;            // RSI oversold level

// Risk & margin inputs
input double   InpRiskPerTradePct      = 1.0;             // Risk per trade (% of free margin)
input double   InpPerTradeMarginCapPct = 10.0;            // Max margin per trade (% of free margin)
input double   InpMinMarginLevelPct    = 200.0;           // Minimum margin level (%) to allow new trades
input bool     InpUseStopLoss          = true;            // Use SL
input bool     InpUseTakeProfit        = true;            // Use TP
input double   InpSL_ATR_Mult          = 2.0;             // SL = ATR * mult
input double   InpTP_RR_Mult           = 2.0;             // TP = SL * RR
input int      InpATRPeriod            = 14;              // ATR period

// Trailing stop
input bool     InpUseTrailing          = true;            // Enable trailing stop
input double   InpTrail_ATR_Mult       = 1.5;             // Trailing distance = ATR * mult

// Filters
input int      InpMaxSpreadPoints      = 25;              // Max allowed spread (points)
input bool     InpUseSessionFilter     = true;            // Restrict trading hours
input int      InpSessionStartHour     = 7;               // Session start (broker time)
input int      InpSessionEndHour       = 20;              // Session end (broker time, inclusive start, exclusive end)

// One-position-per-symbol
input bool     InpOnePositionPerSymbol = true;

// Misc
input ulong    InpMagic                = 20260823;        // Magic number
input bool     InpPrintDebug           = true;            // Verbose logging

//--- Handles
int    hFastEMA = INVALID_HANDLE;
int    hSlowEMA = INVALID_HANDLE;
int    hRSI     = INVALID_HANDLE;
int    hATR     = INVALID_HANDLE;

//--- Cached symbol properties
int      DigitsSym;
double   PointSym;
double   TickSizeSym;
double   TickValueSym;
double   ContractSizeSym;

//--- Utility logging
void Log(string msg, bool is_error=false)
{
   if(!InpPrintDebug && !is_error) return;
   if(is_error) PrintFormat("[ERROR] %s", msg);
   else         PrintFormat("[INFO] %s", msg);
}

bool GetSymbolInfo(const string sym)
{
   DigitsSym       = (int)SymbolInfoInteger(sym, SYMBOL_DIGITS);
   PointSym        = SymbolInfoDouble(sym, SYMBOL_POINT);
   TickSizeSym     = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE);
   TickValueSym    = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE);
   ContractSizeSym = SymbolInfoDouble(sym, SYMBOL_TRADE_CONTRACT_SIZE);
   if(PointSym<=0 || TickSizeSym<=0 || TickValueSym<=0 || ContractSizeSym<=0)
   {
      Log(StringFormat("Invalid symbol parameters: point=%.10f tick_size=%.10f tick_value=%.5f contract=%.2f", PointSym, TickSizeSym, TickValueSym, ContractSizeSym), true);
      return false;
   }
   return true;
}

bool InAllowedSession()
{
   if(!InpUseSessionFilter) return true;
   datetime now = TimeCurrent();
   int hour = TimeHour(now);
   int startH = MathMax(0, MathMin(23, InpSessionStartHour));
   int endH   = MathMax(0, MathMin(24, InpSessionEndHour));
   if(startH < endH)
      return (hour >= startH && hour < endH);
   // overnight window (e.g., 22 -> 6)
   return (hour >= startH || hour < endH);
}

bool SpreadOK(const string sym)
{
   double ask, bid;
   if(!SymbolInfoDouble(sym, SYMBOL_ASK, ask) || !SymbolInfoDouble(sym, SYMBOL_BID, bid))
   {
      Log("Failed to get bid/ask for spread check", true);
      return false;
   }
   double spread_points = (ask - bid) / PointSym;
   return (spread_points <= InpMaxSpreadPoints);
}

bool HasOpenPosition(const string sym)
{
   for(int i=0; i<PositionsTotal(); ++i)
   {
      if(PositionGet(i))
      {
         if(PositionGetString(POSITION_SYMBOL) == sym && PositionGetInteger(POSITION_MAGIC) == (long)InpMagic)
            return true;
      }
   }
   return false;
}

bool CopyLatest(const int handle, const int bars, double &buffer[])
{
   ArraySetAsSeries(buffer, true);
   int copied = CopyBuffer(handle, 0, 0, bars, buffer);
   if(copied < bars)
   {
      Log(StringFormat("CopyBuffer failed. handle=%d need=%d got=%d err=%d", handle, bars, copied, GetLastError()), true);
      return false;
   }
   return true;
}

// Calculate ATR-based stop distance in points
bool GetATRPoints(const string sym, double &atr_points)
{
   double atr_buf[];
   if(!CopyLatest(hATR, 1, atr_buf)) return false;
   double atr_price = atr_buf[0];
   atr_points = atr_price / PointSym; // convert price to points
   return (atr_points > 0);
}

// Determine trade direction based on EMA cross and RSI filter
int GetSignal(const string sym)
{
   double fast[], slow[], rsi[];
   if(!CopyLatest(hFastEMA, 2, fast)) return 0;
   if(!CopyLatest(hSlowEMA, 2, slow)) return 0;
   if(!CopyLatest(hRSI,     1, rsi )) return 0;

   // EMA cross (use previous bar cross confirmation)
   double fast_prev = fast[1];
   double slow_prev = slow[1];
   double fast_curr = fast[0];
   double slow_curr = slow[0];

   bool bull_cross = (fast_prev <= slow_prev) && (fast_curr > slow_curr);
   bool bear_cross = (fast_prev >= slow_prev) && (fast_curr < slow_curr);

   if(bull_cross && rsi[0] < InpRSIOversold) return ORDER_TYPE_BUY;
   if(bear_cross && rsi[0] > InpRSIOverbought) return ORDER_TYPE_SELL;
   return 0;
}

// Compute volume using OrderCalcMargin with free-margin and margin-level checks and per-trade margin cap
bool ComputeVolumeByMargin(const string sym, const ENUM_ORDER_TYPE order_type, const double sl_price, double &volume_out, double &sl_points_out)
{
   volume_out = 0.0;
   sl_points_out = 0.0;

   // Ensure quotes
   double bid, ask;
   if(!SymbolInfoDouble(sym, SYMBOL_BID, bid) || !SymbolInfoDouble(sym, SYMBOL_ASK, ask))
   {
      Log("Failed to read bid/ask for sizing", true);
      return false;
   }
   double price = (order_type == ORDER_TYPE_BUY ? ask : bid);

   // ATR-based SL distance
   double atr_pts;
   if(!GetATRPoints(sym, atr_pts))
   {
      Log("Failed to compute ATR for SL", true);
      return false;
   }
   double sl_pts = MathMax(atr_pts * InpSL_ATR_Mult, TickSizeSym / PointSym);
   sl_points_out = sl_pts;

   // Pip value approximation per lot
   // We'll determine volume by iteratively solving margin constraint and basic risk (% of free margin)
   double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
   double equity      = AccountInfoDouble(ACCOUNT_EQUITY);
   double margin      = AccountInfoDouble(ACCOUNT_MARGIN);
   double margin_level_pct = (margin > 0.0 ? (equity / margin) * 100.0 : 10000.0);

   if(margin_level_pct < InpMinMarginLevelPct)
   {
      Log(StringFormat("Margin level %.2f%% below minimum %.2f%%", margin_level_pct, InpMinMarginLevelPct));
      return false;
   }

   if(free_margin <= 0.0)
   {
      Log("No free margin available", true);
      return false;
   }

   // Caps in currency
   double risk_cap     = free_margin * (InpRiskPerTradePct / 100.0);
   double margin_cap   = free_margin * (InpPerTradeMarginCapPct / 100.0);

   // Symbol trading constraints
   double vol_min   = SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN);
   double vol_max   = SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX);
   double vol_step  = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
   if(vol_min<=0 || vol_max<=0 || vol_step<=0)
   {
      Log("Invalid volume constraints from symbol", true);
      return false;
   }

   // Determine stop distance in price for risk calc
   double sl_distance_price = sl_pts * PointSym;

   // Get tick value per lot (approx position value per point)
   // Convert 1 point P/L per lot
   double point_value_per_lot = (TickValueSym * (PointSym / TickSizeSym));
   if(point_value_per_lot <= 0)
   {
      Log("Invalid point value per lot", true);
      return false;
   }

   // Target volume by risk: risk_cap = volume * (sl_pts * point_value_per_lot)
   double vol_by_risk = risk_cap / (sl_pts * point_value_per_lot);

   // Now enforce margin cap using OrderCalcMargin
   // We'll binary search volume in [vol_min, vol_upper] where margin <= margin_cap
   double vol_upper = MathMin(vol_max, MathMax(vol_min, vol_by_risk));
   if(vol_upper < vol_min) vol_upper = vol_min;

   auto CalcMarginForVol = [&](double v)->double
   {
      double need_margin = 0.0;
      // MARKET order margin estimation
      if(!OrderCalcMargin(order_type, sym, v, price, need_margin))
      {
         int err = GetLastError();
         ResetLastError();
         Log(StringFormat("OrderCalcMargin failed vol=%.2f err=%d", v, err), true);
         return -1.0;
      }
      return need_margin;
   };

   // If margin for vol_min already exceeds cap, try to reduce to 0 (reject trade)
   double m_min = CalcMarginForVol(vol_min);
   if(m_min < 0) return false;
   if(m_min > margin_cap)
   {
      Log(StringFormat("Margin for min vol(%.2f)=%.2f exceeds cap %.2f", vol_min, m_min, margin_cap));
      return false;
   }

   // Expand upper bound if under cap but risk suggests higher
   double m_upper = CalcMarginForVol(vol_upper);
   if(m_upper < 0) return false;
   if(m_upper > margin_cap)
   {
      // shrink using binary search
      double lo = vol_min, hi = vol_upper, best = vol_min;
      for(int i=0;i<30;++i)
      {
         double mid = MathFloor(((lo+hi)/2.0)/vol_step+0.5)*vol_step;
         mid = MathMax(vol_min, MathMin(vol_max, mid));
         double m = CalcMarginForVol(mid);
         if(m < 0) return false;
         if(m <= margin_cap)
         {
            best = mid;
            lo = mid + vol_step;
         }
         else
         {
            hi = mid - vol_step;
         }
         if(MathAbs(hi-lo) < vol_step) break;
      }
      vol_upper = MathMax(vol_min, best);
   }

   // Final volume respects both risk-based and margin-cap constraints
   double volume = MathFloor(vol_upper/vol_step+0.0)*vol_step; // floor to step
   volume = MathMax(vol_min, MathMin(vol_max, volume));

   if(volume <= 0.0)
   {
      Log("Computed volume <= 0", true);
      return false;
   }

   // Final safety margin check including current free margin
   double need_margin_final = 0.0;
   if(!OrderCalcMargin(order_type, sym, volume, price, need_margin_final))
   {
      int err = GetLastError();
      ResetLastError();
      Log(StringFormat("Final OrderCalcMargin failed err=%d", err), true);
      return false;
   }
   if(need_margin_final > margin_cap)
   {
      Log(StringFormat("Final margin %.2f exceeds cap %.2f", need_margin_final, margin_cap));
      return false;
   }
   if(need_margin_final > free_margin)
   {
      Log(StringFormat("Final margin %.2f exceeds free margin %.2f", need_margin_final, free_margin));
      return false;
   }

   // Additional margin level check after hypothetical allocation
   double equity_new = equity; // unchanged by opening hypothetical order
   double margin_new = margin + need_margin_final;
   double ml_new = (margin_new>0 ? (equity_new/margin_new)*100.0 : 10000.0);
   if(ml_new < InpMinMarginLevelPct)
   {
      Log(StringFormat("Projected margin level %.2f%% below minimum %.2f%%", ml_new, InpMinMarginLevelPct));
      return false;
   }

   volume_out = NormalizeDouble(volume, (int)SymbolInfoInteger(sym, SYMBOL_VOLUME_DIGITS));
   return true;
}

// Build SL/TP prices based on direction and ATR
bool BuildSLTP(const string sym, const ENUM_ORDER_TYPE type, const double sl_points, double &sl_price, double &tp_price)
{
   sl_price = 0.0; tp_price = 0.0;
   double bid, ask;
   if(!SymbolInfoDouble(sym, SYMBOL_BID, bid) || !SymbolInfoDouble(sym, SYMBOL_ASK, ask))
   {
      Log("Failed to read bid/ask for SL/TP", true);
      return false;
   }
   double price = (type == ORDER_TYPE_BUY ? ask : bid);

   double sl_dist = sl_points * PointSym;
   if(type == ORDER_TYPE_BUY)
   {
      sl_price = price - sl_dist;
      if(InpUseTakeProfit)
         tp_price = price + sl_dist * InpTP_RR_Mult;
   }
   else
   {
      sl_price = price + sl_dist;
      if(InpUseTakeProfit)
         tp_price = price - sl_dist * InpTP_RR_Mult;
   }

   // Normalize to tick size grid
   sl_price = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE) > 0
              ? MathRound(sl_price / TickSizeSym) * TickSizeSym
              : NormalizeDouble(sl_price, DigitsSym);
   if(InpUseTakeProfit)
      tp_price = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE) > 0
                 ? MathRound(tp_price / TickSizeSym) * TickSizeSym
                 : NormalizeDouble(tp_price, DigitsSym);
   return true;
}

void TrailPosition(const string sym)
{
   if(!InpUseTrailing) return;
   if(!PositionSelectByTicket(0)){} // noop to ensure API warmed

   for(int i=0; i<PositionsTotal(); ++i)
   {
      if(!PositionGet(i)) continue;
      string psym   = PositionGetString(POSITION_SYMBOL);
      long   pmagic = PositionGetInteger(POSITION_MAGIC);
      if(psym != sym || pmagic != (long)InpMagic) continue;

      long   type   = PositionGetInteger(POSITION_TYPE);
      double price_open = PositionGetDouble(POSITION_PRICE_OPEN);
      double sl        = PositionGetDouble(POSITION_SL);
      double bid = 0, ask = 0;
      SymbolInfoDouble(sym, SYMBOL_BID, bid);
      SymbolInfoDouble(sym, SYMBOL_ASK, ask);

      double atr_pts;
      if(!GetATRPoints(sym, atr_pts)) continue;
      double trail_dist = atr_pts * InpTrail_ATR_Mult * PointSym;

      if(type == POSITION_TYPE_BUY)
      {
         double new_sl = bid - trail_dist;
         if(new_sl > sl && new_sl < bid)
         {
            trade.SetAsyncMode(false);
            trade.PositionModify(psym, new_sl, PositionGetDouble(POSITION_TP));
            if(trade.ResultRetcode() != TRADE_RETCODE_DONE)
               Log(StringFormat("Trail modify failed BUY ret=%d", trade.ResultRetcode()));
         }
      }
      else if(type == POSITION_TYPE_SELL)
      {
         double new_sl = ask + trail_dist;
         if((sl==0.0 || new_sl < sl) && new_sl > ask)
         {
            trade.SetAsyncMode(false);
            trade.PositionModify(psym, new_sl, PositionGetDouble(POSITION_TP));
            if(trade.ResultRetcode() != TRADE_RETCODE_DONE)
               Log(StringFormat("Trail modify failed SELL ret=%d", trade.ResultRetcode()));
         }
      }
   }
}

bool OpenPosition(const string sym, const ENUM_ORDER_TYPE type)
{
   double sl_points, volume;
   double sl_price=0, tp_price=0;
   if(!ComputeVolumeByMargin(sym, type, 0.0, volume, sl_points)) return false;
   if(!BuildSLTP(sym, type, sl_points, sl_price, tp_price)) return false;

   trade.SetExpertMagicNumber(InpMagic);
   trade.SetAsyncMode(false);

   bool ok=false;
   if(type == ORDER_TYPE_BUY)
   {
      ok = trade.Buy(volume, sym, 0.0, InpUseStopLoss ? sl_price : 0.0, InpUseTakeProfit ? tp_price : 0.0, "EMA_RSI Buy");
   }
   else if(type == ORDER_TYPE_SELL)
   {
      ok = trade.Sell(volume, sym, 0.0, InpUseStopLoss ? sl_price : 0.0, InpUseTakeProfit ? tp_price : 0.0, "EMA_RSI Sell");
   }
   else return false;

   int ret = trade.ResultRetcode();
   if(!ok || ret != TRADE_RETCODE_DONE)
   {
      Log(StringFormat("Order send failed ret=%d vol=%.2f sl=%.5f tp=%.5f", ret, volume, sl_price, tp_price), true);
      return false;
   }
   Log(StringFormat("Order placed: %s vol=%.2f sl=%.5f tp=%.5f", type==ORDER_TYPE_BUY?"BUY":"SELL", volume, sl_price, tp_price));
   return true;
}

int OnInit()
{
   string sym = InpSymbol;
   if(!SymbolSelect(sym, true))
   {
      Log(StringFormat("Failed to select symbol %s", sym), true);
      return INIT_FAILED;
   }
   if(!GetSymbolInfo(sym)) return INIT_FAILED;

   // Create indicators on InpTF, applied to sym
   hFastEMA = iMA(sym, InpTF, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
   hSlowEMA = iMA(sym, InpTF, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
   hRSI     = iRSI(sym, InpTF, InpRSIPeriod, PRICE_CLOSE);
   hATR     = iATR(sym, InpTF, InpATRPeriod);

   if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
   {
      Log("Failed to create indicators", true);
      return INIT_FAILED;
   }

   Log("Initialization successful");
   return INIT_SUCCEEDED;
}

void OnDeinit(const int reason)
{
   if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
   if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
   if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
   if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
   string sym = InpSymbol;

   // Filters: spread and session
   if(!SpreadOK(sym)) return;
   if(!InAllowedSession()) return;

   // One-position-per-symbol
   if(InpOnePositionPerSymbol && HasOpenPosition(sym))
   {
      TrailPosition(sym);
      return;
   }

   // Only evaluate signals on a new bar for stability
   static datetime last_bar_time = 0;
   datetime cur_bar_time = iTime(sym, InpTF, 0);
   if(cur_bar_time == 0) return;
   if(cur_bar_time == last_bar_time)
   {
      // still can trail existing pos
      TrailPosition(sym);
      return;
   }
   last_bar_time = cur_bar_time;

   int signal = GetSignal(sym);
   if(signal == ORDER_TYPE_BUY || signal == ORDER_TYPE_SELL)
      OpenPosition(sym, (ENUM_ORDER_TYPE)signal);

   // Manage trailing after any action
   TrailPosition(sym);
}

